Object.assign(GL,{
 ntube:{t:"神經管、神經嵴 neural tube / neural crest",d:"胚胎外胚層形成的構造：<b>神經管</b>發育成腦與脊髓；<b>神經嵴</b>形成周邊神經節、腎上腺髓質等。",e:"孕前補充葉酸可降低神經管缺陷。",c:"8.1"},
 telen:{t:"端腦、間腦、中腦、後腦、髓腦",d:"胚胎第 5 週腦的五個區域：<b>端腦</b>→大腦；<b>間腦</b>→視丘、下視丘；<b>中腦</b>；<b>後腦</b>→橋腦、小腦；<b>髓腦</b>→延腦。",c:"8.1"},
 ventricle:{t:"腦室 ventricles",d:"腦內四個相連的腔室（兩個側腦室、第三、第四腦室），充滿腦脊髓液。",c:"8.1"},
 csf:{t:"腦脊髓液 cerebrospinal fluid（CSF）",d:"充滿腦室與蛛網膜下腔的液體，由脈絡叢產生、蛛網膜絨毛回收；保護緩衝、運送養分與廢物。約 140–200 mL。",c:"8.1"},
 choroid:{t:"脈絡叢 choroid plexus",d:"腦室中由微血管與室管膜細胞組成的構造，負責產生腦脊髓液。",c:"8.1"},
 cerebrum:{t:"大腦 cerebrum",d:"腦最大的部分，分左右半球，表面是皮質（灰質），負責感覺、運動、思考、語言、記憶等高階功能。",c:"8.2"},
 cortex:{t:"大腦皮質 cerebral cortex",d:"大腦表面 2–4 mm 厚的灰質，有腦迴與腦溝，分為額、頂、顳、枕葉。",c:"8.2"},
 cc:{t:"胼胝體 corpus callosum",d:"連接左右大腦半球的大束白質，讓兩半球交換訊息。",c:"8.2"},
 lobes:{t:"額葉、頂葉、顳葉、枕葉",d:"<b>額葉</b>：運動、計畫、人格、說話（布洛卡）。<b>頂葉</b>：體感覺。<b>顳葉</b>：聽覺、記憶、語言理解（威尼克）。<b>枕葉</b>：視覺。",c:"8.2"},
 precentral:{t:"中央前迴、中央後迴",d:"<b>中央前迴</b>（額葉）＝初級運動區；<b>中央後迴</b>（頂葉）＝初級體感覺區。身體各部位依精細程度占不同大小的面積（小矮人圖）。",c:"8.2"},
 eeg:{t:"腦電圖 electroencephalogram（EEG）",d:"從頭皮記錄大腦皮質電活動的檢查，用於診斷癲癇與研究睡眠。",c:"8.2"},
 basal:{t:"基底核 basal nuclei",d:"大腦深部的灰質團（尾核、殼核＝紋狀體，蒼白球），負責啟動與調控動作；帕金森氏症、杭丁頓氏舞蹈症與它有關。",c:"8.2"},
 striatum:{t:"紋狀體 striatum",d:"基底核中的尾核加殼核，接收黑質的多巴胺。",c:"8.2"},
 huntington:{t:"杭丁頓氏舞蹈症 Huntington's disease",d:"huntingtin 基因的 CAG 重複過多造成的遺傳疾病，紋狀體神經元退化，出現不自主舞蹈樣動作與失智。",c:"8.2"},
 lateral:{t:"大腦側化 cerebral lateralization",d:"左右大腦半球功能的不對稱：多數人<b>左</b>半球主導語言、邏輯、數學；<b>右</b>半球主導空間、臉孔、音樂、情緒。",c:"8.2（國考）"},
 broca:{t:"布洛卡區 Broca's area",d:"左額葉下部的說話產出區；受損 → 表達性失語：說話費力、字少，但理解大致正常。",n:"1861 年法國醫師 Paul Broca 描述。",c:"8.2"},
 wernicke:{t:"威尼克區 Wernicke's area",d:"左顳葉上部的語言理解區；受損 → 接受性失語：說得流利但無意義，且聽不懂。",n:"德國醫師 Carl Wernicke 描述。",c:"8.2"},
 aphasia:{t:"失語症 aphasia",d:"腦損傷造成的語言能力障礙，常見於左腦中風。",c:"8.2"},
 limbic:{t:"邊緣系統 limbic system",d:"圍繞腦幹上方的一圈構造（扣帶迴、海馬迴、杏仁核、部分下視丘等），負責情緒、動機與記憶。",c:"8.2"},
 amygdala:{t:"杏仁核 amygdala",d:"顳葉內側的杏仁狀構造，處理恐懼與威脅、情緒記憶。",c:"8.2"},
 stm:{t:"短期記憶、長期記憶",d:"<b>短期</b>：保存數秒到數分鐘（工作記憶，前額葉）。<b>長期</b>：經鞏固後保存；陳述性（事實事件，需海馬迴）、非陳述性（技能，基底核與小腦）。",c:"8.2"},
 consol:{t:"記憶鞏固 memory consolidation",d:"把短期記憶轉成長期記憶的過程，需要海馬迴與新的蛋白質合成；睡眠有助於鞏固。",c:"8.2"},
 diencephalon:{t:"間腦 diencephalon",d:"大腦與中腦之間的部分，包括視丘、上視丘（松果腺）、下視丘。",c:"8.3"},
 thalamus:{t:"視丘 thalamus",d:"間腦最大的部分，是除嗅覺外所有感覺傳到大腦皮質前的<b>轉運與過濾站</b>，也參與運動迴路與清醒。",c:"8.3"},
 pineal:{t:"松果腺 pineal gland",d:"上視丘的小腺體，在黑暗時分泌褪黑激素，調節晝夜節律。",c:"8.3；第 11 章"},
 melatonin:{t:"褪黑激素 melatonin",d:"松果腺由血清素轉成的激素，晚上黑暗時分泌增加、光線抑制，促進睡眠與調節生理時鐘。",c:"8.3；第 11 章"},
 scn:{t:"視交叉上核 suprachiasmatic nucleus",d:"下視丘中的「主時鐘」，接收視網膜的光訊號，設定約 24 小時的晝夜節律。",c:"8.3"},
 feeding:{t:"攝食中樞、飽食中樞",d:"<b>外側下視丘區</b>＝攝食（飢餓）中樞，受損 → 不吃、消瘦；<b>腹內側核</b>＝飽食中樞，受損 → 吃不停、肥胖。",c:"8.3；第 19 章"},
 circadian:{t:"晝夜節律 circadian rhythm",d:"約 24 小時週期的生理變化（睡眠、體溫、激素如皮質醇與褪黑激素），由視交叉上核控制。",n:"circa（大約）＋ dies（一天）。",c:"8.3；第 11 章"},
 brainstem:{t:"腦幹 brain stem",d:"中腦＋橋腦＋延腦，含維生中樞與多數腦神經核。",c:"8.4"},
 midbrain:{t:"中腦 midbrain",d:"腦幹最上部：上丘（視覺反射）、下丘（聽覺反射）、黑質（多巴胺）、紅核。",c:"8.4"},
 sn:{t:"黑質 substantia nigra",d:"中腦中含黑色素的多巴胺神經元群，投射到紋狀體控制動作；退化造成帕金森氏症。",c:"8.4；第 7 章"},
 pons:{t:"橋腦 pons",d:"連接延腦、中腦與小腦的部分，含部分腦神經核與呼吸調節中樞。",c:"8.4；第 16 章"},
 medulla:{t:"延腦 medulla oblongata",d:"腦幹最下部、接脊髓；含<b>呼吸中樞、心血管中樞</b>及嘔吐、吞嚥、咳嗽中樞；錐體徑在此交叉。",c:"8.4；第 14、16 章"},
 cerebellum:{t:"小腦 cerebellum",d:"比較「想做的動作」與「實際動作」並即時修正：協調、平衡、姿勢、運動學習。受損 → 運動失調。",c:"8.4；第 12 章"},
 ataxia:{t:"運動失調 ataxia",d:"小腦或其路徑受損造成的動作不協調：走路不穩、意向性顫抖、說話含糊。",c:"8.4"},
 ras:{t:"網狀活化系統 reticular activating system（RAS）",d:"腦幹網狀結構中向上投射到視丘與皮質的部分，負責維持清醒與注意力；受損可致昏迷。",c:"8.4"},
 dhorn:{t:"背角、腹角 dorsal / ventral horn",d:"脊髓 H 形灰質的部分：<b>背角</b>接收感覺；<b>腹角</b>有支配骨骼肌的運動神經元。",c:"8.5"},
 droot:{t:"背根、腹根 dorsal / ventral root",d:"脊神經連到脊髓的兩條根：<b>背根</b>帶感覺纖維進入（有背根神經節）；<b>腹根</b>帶運動纖維出去。",c:"8.5"},
 ascend:{t:"上行徑、下行徑 ascending / descending tracts",d:"脊髓白質中的神經徑：<b>上行</b>把感覺送到腦；<b>下行</b>把運動命令送到脊髓。",c:"8.5"},
 stt:{t:"脊髓視丘徑 spinothalamic tract",d:"傳送<b>痛覺、溫度</b>、粗略觸覺的上行徑；在脊髓同一節段經前白連合交叉到對側。",c:"8.5；第 10 章"},
 dcml:{t:"背柱—內側蹄系 dorsal column–medial lemniscus",d:"傳送精細觸覺、震動、本體感覺的上行徑；在延腦才交叉。",c:"8.5；第 10 章"},
 proprio:{t:"本體感覺 proprioception",d:"感知自己肢體位置與動作的感覺，由肌梭、肌腱與關節的感受器提供。",c:"8.5；第 10、12 章"},
 pyramidal:{t:"錐體徑（皮質脊髓徑）pyramidal / corticospinal tract",d:"從運動皮質直達脊髓的下行徑，控制精細隨意動作；約 85% 在延腦錐體交叉。",n:"在延腦腹側形成像金字塔（錐體）的隆起。",c:"8.5"},
 extrapyr:{t:"錐體外徑 extrapyramidal tracts",d:"由腦幹（紅核、網狀結構、前庭核）發出的下行徑，調節姿勢、平衡、肌肉張力。",c:"8.5"},
 decuss:{t:"交叉 decussation",d:"神經徑越過中線到對側，所以一側大腦管對側身體。",c:"8.5"},
 cranial:{t:"腦神經 cranial nerves",d:"從腦發出的 12 對神經（I 嗅、II 視、III 動眼、IV 滑車、V 三叉、VI 外旋、VII 顏面、VIII 前庭耳蝸、IX 舌咽、X 迷走、XI 副、XII 舌下）。",c:"8.6"},
 vagus:{t:"迷走神經 vagus nerve（X）",d:"最長的腦神經，提供胸腹內臟（心、肺、消化道）大部分的副交感支配與內臟感覺。",n:"vagus＝拉丁文「遊走」，因為它分布範圍很廣。",c:"8.6；第 9、18 章"},
 spinaln:{t:"脊神經 spinal nerves",d:"31 對（頸 8、胸 12、腰 5、薦 5、尾 1），都是含感覺與運動纖維的混合神經。",c:"8.6"},
 dermatome:{t:"皮節 dermatome",d:"一對脊神經的感覺纖維所分布的皮膚區域。",e:"帶狀皰疹沿皮節呈帶狀分布。",c:"8.6"},
 reflexarc:{t:"反射弧 reflex arc",d:"反射的神經路徑：感受器 → 感覺神經元 → 整合中心（脊髓或腦幹）→ 運動神經元 → 動器。",c:"8.6；第 12 章"},
 kneejerk:{t:"膝跳反射 knee-jerk reflex",d:"敲膝蓋下方韌帶 → 股四頭肌被拉長 → 肌梭偵測 → 單突觸反射使同肌收縮、小腿踢出；屬牽張反射。",c:"8.6；第 12 章"},
 withdraw:{t:"縮回反射、對側伸肌反射",d:"踩到尖物時同側屈肌收縮把腳縮回（多突觸），同時對側伸肌收縮支撐身體。",c:"8.6"}
});
