Object.assign(GL,{
 pregang:{t:"節前、節後神經元 preganglionic / postganglionic",d:"自主神經的兩段：<b>節前</b>神經元在腦幹或脊髓，軸突到自主神經節；<b>節後</b>神經元在神經節內，軸突到動器。",c:"9.1"},
 autogang:{t:"自主神經節 autonomic ganglion",d:"節前神經元與節後神經元形成突觸的地方；所有神經節都用 ACh 與菸鹼型受體。",c:"9.1"},
 symp:{t:"交感神經 sympathetic division",d:"從胸腰段（T1–L2）發出，神經節在脊柱旁（交感鏈），節前短、節後長；啟動「戰或逃」反應，常全身同時活化。",c:"9.2"},
 parasymp:{t:"副交感神經 parasympathetic division",d:"從腦幹（III、VII、IX、X）與薦段（S2–S4）發出，神經節在器官旁，節前長、節後短；負責「休息與消化」，作用較局部。",c:"9.2"},
 schain:{t:"交感神經鏈 sympathetic chain",d:"脊柱兩側上下相連的椎旁神經節，讓交感訊號能在不同節段間擴散。",c:"9.2"},
 termgang:{t:"終末神經節 terminal ganglia",d:"副交感的神經節，位於標的器官旁或器官壁內。",c:"9.2"},
 massact:{t:"大量放電 mass activation",d:"交感神經在緊急狀況下全身同時活化的特性，因節前纖維分歧多並有腎上腺髓質參與。",c:"9.2"},
 admed:{t:"腎上腺髓質 adrenal medulla",d:"腎上腺的內層，本質是特化的交感節後神經元，受刺激時分泌腎上腺素（約 80%）與正腎上腺素到血液。",c:"9.2；第 11 章"},
 fightflight:{t:"戰或逃 fight or flight",d:"交感神經主導的緊急反應：心跳加快、血壓升高、瞳孔放大、支氣管擴張、血糖上升、消化變慢。",c:"9.2"},
 restdigest:{t:"休息與消化 rest and digest",d:"副交感神經主導的狀態：心跳變慢、消化液分泌與腸胃蠕動增加、儲存能量。",c:"9.2"},
 cholin:{t:"膽鹼性、腎上腺素性 cholinergic / adrenergic",d:"<b>膽鹼性</b>：釋放乙醯膽鹼的神經元（所有節前、副交感節後、交感到汗腺）。<b>腎上腺素性</b>：釋放正腎上腺素（多數交感節後）。",c:"9.3"},
 adrrec:{t:"腎上腺素性受體 adrenergic receptors",d:"正腎上腺素與腎上腺素的受體：<b>α1</b> 血管收縮、瞳孔放大；<b>α2</b> 抑制 NE 釋放與胰島素；<b>β1</b> 心跳↑、腎素↑；<b>β2</b> 支氣管擴張、肝醣分解；<b>β3</b> 脂肪分解。",c:"9.3；第 11、14 章"},
 alpha1:{t:"α1 受體",d:"多數血管平滑肌收縮（血壓↑）、瞳孔放大、括約肌收縮；經 IP₃ 與 Ca²⁺。",c:"9.3"},
 alpha2:{t:"α2 受體",d:"交感末梢的突觸前受體，抑制正腎上腺素釋放（負回饋）；胰島 β 細胞上抑制胰島素分泌。",c:"9.3"},
 beta1:{t:"β1 受體",d:"主要在心臟：心跳加快、收縮力增強；也在腎臟促進腎素分泌。",c:"9.3；第 14 章"},
 beta2:{t:"β2 受體",d:"支氣管平滑肌放鬆（擴張）、骨骼肌與冠狀血管擴張、子宮放鬆、肝醣分解。",e:"氣喘吸入劑 albuterol 是 β2 致效劑。",c:"9.3；第 16 章"},
 beta3:{t:"β3 受體",d:"脂肪組織中促進脂肪分解；也使膀胱放鬆。",c:"9.3"},
 betablock:{t:"β 阻斷劑 β-blockers",d:"阻斷 β 受體的藥：降低心跳與血壓。非選擇性者同時阻斷 β2，可能引起支氣管收縮。",c:"9.3；第 14 章"},
 agonist:{t:"致效劑、拮抗劑 agonist / antagonist",d:"<b>致效劑</b>：模仿天然物質、活化受體的藥。<b>拮抗劑（阻斷劑）</b>：佔住受體但不活化，阻止天然物質作用。",c:"9.3"},
 nanc:{t:"非腎上腺素非膽鹼性 NANC",d:"既不用 ACh 也不用 NE 的自主神經傳遞，使用 ATP、一氧化氮、VIP 等。",c:"9.3"},
 dualinn:{t:"雙重支配 dual innervation",d:"同一器官同時受交感與副交感支配，關係可為<b>拮抗</b>（心臟、瞳孔、腸胃）、<b>互補</b>（唾液腺）、<b>協同</b>（生殖、排尿）。",c:"9.3"},
 vagaltone:{t:"迷走張力 vagal tone",d:"安靜時迷走神經持續的抑制作用，使靜止心跳（約 70 次）低於節律點本身的速率（約 100 次）。",c:"9.3；第 13、14 章"},
 baroreflex:{t:"壓力感受器反射 baroreceptor reflex",d:"頸動脈竇與主動脈弓的壓力感受器偵測血壓，經延腦心血管中樞即時調整心跳與血管，維持血壓穩定。",c:"9.4；第 14 章"},
 vasovagal:{t:"血管迷走性昏厥 vasovagal syncope",d:"情緒或疼痛（如看到血）引起副交感突然增強、交感撤退，心跳變慢、血壓下降，腦血流不足而暈倒。",c:"9.4"},
 biofeedback:{t:"生物回饋 biofeedback",d:"用儀器把心跳、血壓、肌肉張力等顯示出來，讓人學習有意識地調整它們的方法。",c:"9.4"}
});
Object.assign(GL_ALIAS,{
 "節前":"pregang","節後":"pregang","節前神經元":"pregang","節後神經元":"pregang","自主神經節":"autogang","交感":"symp","副交感":"parasymp",
 "交感神經鏈":"schain","交感鏈":"schain","終末神經節":"termgang","大量放電":"massact","腎上腺髓質":"admed","戰或逃":"fightflight",
 "休息與消化":"restdigest","膽鹼性":"cholin","腎上腺素性":"cholin","腎上腺素性受體":"adrrec","α1":"alpha1","α2":"alpha2","β1":"beta1","β2":"beta2","β3":"beta3",
 "β 阻斷劑":"betablock","致效劑":"agonist","拮抗劑":"agonist","阻斷劑":"agonist","NANC":"nanc","雙重支配":"dualinn","迷走張力":"vagaltone",
 "壓力感受器反射":"baroreflex","血管迷走性昏厥":"vasovagal","生物回饋":"biofeedback"
});

/* ---- end ch09 ---- */
/* ---- ch10 ---- */
Object.assign(GL,{
 chemorec:{t:"化學感受器 chemoreceptors",d:"偵測化學物質的感受器：味蕾、嗅覺，以及偵測血中 O₂、CO₂、pH 的頸動脈體與主動脈體。",c:"10.1；第 16 章"},
 photorec:{t:"光感受器 photoreceptors",d:"偵測光的感受器：視網膜的桿細胞與錐細胞。",c:"10.7"},
 mechanorec:{t:"機械感受器 mechanoreceptors",d:"偵測觸、壓、牽張、振動、聲音、重力的感受器。",c:"10.1"},
 nocirec:{t:"痛覺（傷害）感受器 nociceptors",d:"偵測組織損傷或可能造成損傷的刺激（極端溫度、壓力、化學物質）的游離神經末梢。",c:"10.1、10.2"},
 thermorec:{t:"溫度感受器 thermoreceptors",d:"偵測冷或熱的感受器，經 TRP 通道（如 TRPV1 熱、TRPM8 冷）。",c:"10.2"},
 lsne:{t:"特定神經能量定律 law of specific nerve energies",d:"不論用什麼方式刺激，同一條感覺路徑傳到腦都只產生同一種感覺。",e:"揉眼睛看到光；幻肢痛。",c:"10.1"},
 adequate:{t:"適當刺激 adequate stimulus",d:"感受器最敏感的那一種刺激（如視網膜對光）。",c:"10.1"},
 transduc:{t:"轉導 transduction",d:"感受器把刺激的能量（光、聲、壓、化學）轉換成電訊號的過程。",c:"10.1"},
 genpot:{t:"發生器電位 generator potential",d:"感受器受刺激產生的分級去極化；越強越大，達閾值時在感覺神經上產生動作電位，頻率代表強度。",c:"10.1"},
 tonicrec:{t:"緊張性、相位性感受器 tonic / phasic receptors",d:"<b>緊張性</b>：刺激持續時持續放電（痛覺、肌梭）。<b>相位性</b>：只在刺激開始（與結束）時放電，很快適應（觸壓覺、嗅覺）。",c:"10.1"},
 adaptation:{t:"適應 adaptation",d:"持續相同刺激下感受器反應逐漸減少，使我們忽略不變的背景、注意變化。",c:"10.1"},
 freene:{t:"游離神經末梢 free nerve endings",d:"沒有被囊包覆的感覺神經末梢，偵測痛、溫度、癢。",c:"10.2"},
 meissner:{t:"梅斯納小體、巴齊尼小體",d:"<b>梅斯納小體</b>：無毛皮膚的輕觸感受器。<b>巴齊尼小體</b>：洋蔥狀多層被囊的深壓與振動感受器。兩者都是相位性。",c:"10.2"},
 capsaicin:{t:"辣椒素 capsaicin",d:"辣椒中的成分，活化熱感受器 TRPV1，所以吃辣會覺得「熱、痛」。",c:"10.2"},
 recfield:{t:"感受野 receptive field",d:"一個感覺神經元負責的範圍。感受野越小、越密集，感覺越精細。",c:"10.2、10.8"},
 twopoint:{t:"兩點辨別閾 two-point threshold",d:"皮膚上同時碰觸兩點時，能分辨出是兩點的最短距離；指尖、嘴唇最小。",c:"10.2"},
 latinh:{t:"側抑制 lateral inhibition",d:"受刺激最強的神經元抑制周圍神經元，增強對比，使位置與邊緣更清楚。",c:"10.2、10.8"},
 referred:{t:"轉移痛 referred pain",d:"內臟的痛被感覺成來自同一脊髓節段支配的體表，因兩者的感覺纖維會聚到同一群脊髓神經元。",e:"心臟 → 左肩、左臂內側；膽囊 → 右肩胛。",c:"10.2"},
 tastebud:{t:"味蕾 taste buds",d:"位在舌乳頭等處、由味覺細胞（特化上皮細胞）組成的構造，約 10 天更新；接觸溶在唾液中的分子。",c:"10.3"},
 umami:{t:"鮮味 umami",d:"第五種基本味道，由麩胺酸（味精）與核苷酸（IMP、GMP）引起，代表蛋白質。",n:"日文「旨味」，1908 年池田菊苗從昆布湯中發現。",c:"10.3"},
 gustducin:{t:"味導素 gustducin",d:"甜、苦、鮮味受體所偶聯的 G 蛋白。",c:"10.3"},
 olfactory:{t:"嗅覺上皮、嗅球",d:"<b>嗅覺上皮</b>在鼻腔頂部，含嗅覺受體神經元（可更新）；<b>嗅球</b>在額葉下方，接收嗅神經並直接送到嗅覺皮質與邊緣系統。",c:"10.3"},
 olfrec:{t:"嗅覺受體 olfactory receptors",d:"約 350–400 種 G 蛋白偶聯受體，每個嗅覺神經元只表現一種；不同氣味活化不同組合。",n:"2004 年 Axel 與 Buck 因發現嗅覺受體家族獲諾貝爾獎。",c:"10.3"},
 flavor:{t:"風味 flavor",d:"食物的整體味道＝味覺＋嗅覺（鼻後嗅覺）＋口感與溫度；大部分來自嗅覺。",c:"10.3"},
 vestib:{t:"前庭器 vestibular apparatus",d:"內耳負責平衡的部分：橢圓囊、球囊（直線加速、傾斜）與三個半規管（旋轉）。",c:"10.4"},
 endolymph:{t:"內淋巴、外淋巴 endolymph / perilymph",d:"<b>內淋巴</b>：膜迷路內，K⁺ 很高，毛細胞頂端浸在其中。<b>外淋巴</b>：膜迷路外，類似細胞外液。",c:"10.4、10.5"},
 haircell:{t:"毛細胞 hair cells",d:"內耳的機械感受細胞，頂端有靜纖毛；纖毛往動纖毛（最高處）方向彎曲 → K⁺ 流入去極化。",c:"10.4、10.5"},
 otolith:{t:"耳石、耳石器 otoliths",d:"橢圓囊與球囊中膠質膜上的碳酸鈣小晶體，使膜在頭傾斜或直線加速時滑動，彎曲毛細胞纖毛。",c:"10.4"},
 utricle:{t:"橢圓囊、球囊 utricle / saccule",d:"耳石器。<b>橢圓囊</b>偵測水平方向的加速與傾斜；<b>球囊</b>偵測垂直方向的加速。",c:"10.4"},
 semicirc:{t:"半規管 semicircular canals",d:"三個互相垂直的管道，內淋巴在頭部旋轉時推動壺腹頂，偵測旋轉加速。",c:"10.4"},
 cupula:{t:"壺腹頂 cupula",d:"半規管壺腹中包住毛細胞纖毛的膠質帽，被內淋巴推動時使纖毛彎曲。",c:"10.4"},
 vertigo:{t:"眩暈、眼球震顫 vertigo / nystagmus",d:"<b>眩暈</b>：天旋地轉的感覺，前庭訊號與視覺不一致時產生。<b>眼球震顫</b>：眼球不自主來回擺動。",c:"10.4"},
 tympanic:{t:"鼓膜 tympanic membrane",d:"外耳與中耳之間的薄膜，受聲波振動。",c:"10.5"},
 ossicles:{t:"聽小骨 ossicles",d:"中耳的三塊小骨：槌骨、砧骨、鐙骨，把鼓膜振動放大約 20 倍傳到卵圓窗。",c:"10.5"},
 ovalwin:{t:"卵圓窗、圓窗 oval / round window",d:"<b>卵圓窗</b>：鐙骨踩著的內耳入口，振動由此進入耳蝸外淋巴。<b>圓窗</b>：耳蝸另一端的膜，讓壓力波釋放回中耳。",c:"10.5"},
 eust:{t:"耳咽管 auditory (Eustachian) tube",d:"連接中耳與咽部的管道，吞嚥或打哈欠時打開，平衡中耳與外界的氣壓。",c:"10.5"},
 cochlea:{t:"耳蝸 cochlea",d:"內耳盤繞約 2¾ 圈的聽覺器官，內有基底膜與柯蒂氏器。",n:"拉丁文「蝸牛殼」。",c:"10.5"},
 basilar:{t:"基底膜 basilar membrane（耳蝸）",d:"耳蝸蝸管底部的膜，上面坐著柯蒂氏器；底部窄硬對高音、頂部寬軟對低音（位置理論）。",c:"10.5"},
 corti:{t:"柯蒂氏器 organ of Corti（spiral organ）",d:"耳蝸基底膜上的聽覺感受器，由內毛細胞（傳訊）、外毛細胞（放大）與支持細胞組成，纖毛抵住上方的覆膜。",c:"10.5"},
 deaf:{t:"傳導性、感音神經性耳聾",d:"<b>傳導性</b>：外耳或中耳傳導受阻（耳垢、中耳炎、耳硬化症），助聽器有效。<b>感音神經性</b>：毛細胞或聽神經受損（噪音、老化、藥物），可考慮人工耳蝸。",c:"10.5"},
 cornea:{t:"角膜 cornea",d:"眼球最前方透明、無血管的部分，提供約 2/3 的折射力（固定）。",c:"10.6"},
 lens:{t:"水晶體 lens",d:"虹膜後方的雙凸透明構造，提供約 1/3 的折射力，可改變形狀調節焦距。變混濁＝白內障。",c:"10.6"},
 iris:{t:"虹膜、瞳孔 iris / pupil",d:"<b>虹膜</b>是眼睛有顏色的部分，含環狀肌（副交感，縮小瞳孔）與輻射狀肌（交感，放大瞳孔）；中間的孔是<b>瞳孔</b>。",c:"10.6；第 9 章"},
 ciliary:{t:"睫狀體、懸韌帶 ciliary body / suspensory ligament",d:"<b>睫狀體</b>含睫狀肌並分泌房水；<b>懸韌帶</b>連接睫狀體與水晶體。看近時睫狀肌收縮、懸韌帶放鬆、水晶體變圓。",c:"10.6"},
 aqueous:{t:"房水、玻璃體 aqueous humor / vitreous body",d:"<b>房水</b>：角膜與水晶體之間的液體，由睫狀體分泌、經許萊姆氏管排出；排出受阻 → 青光眼。<b>玻璃體</b>：水晶體後的膠狀物。",c:"10.6"},
 accom:{t:"調節作用 accommodation",d:"水晶體改變形狀以對焦遠近：看近時睫狀肌收縮 → 懸韌帶鬆 → 水晶體變圓。",c:"10.6"},
 refraction:{t:"折射 refraction",d:"光線進入密度不同的介質時方向彎折；眼睛靠角膜與水晶體折射，在視網膜上成像。",c:"10.6"},
 myopia:{t:"近視、遠視 myopia / hyperopia",d:"<b>近視</b>：眼球太長或折射太強，成像在視網膜前，看遠模糊，用凹透鏡。<b>遠視</b>：眼球太短，成像在後，用凸透鏡。",c:"10.6"},
 presby:{t:"老花眼 presbyopia",d:"年紀增長水晶體失去彈性，看近時無法變圓，近點變遠；用凸透鏡（老花眼鏡）。",n:"presby-＝老。",c:"10.6"},
 astig:{t:"散光 astigmatism",d:"角膜或水晶體不同方向的曲度不同，使某些方向的線條模糊；用柱狀透鏡矯正。",c:"10.6"},
 glaucoma:{t:"青光眼 glaucoma",d:"房水排出受阻使眼壓升高，壓迫並損傷視神經，造成視野缺損甚至失明。",c:"10.6"},
 cataract:{t:"白內障 cataract",d:"水晶體變混濁，與老化、糖尿病、紫外線有關；以手術更換人工水晶體。",c:"10.6"},
 retina:{t:"視網膜 retina",d:"眼球最內層的神經組織，含感光細胞（桿、錐）、雙極細胞、神經節細胞，把光轉成神經訊號。",c:"10.7"},
 rods:{t:"桿細胞、錐細胞 rods / cones",d:"<b>桿細胞</b>：約 1.2 億、在周邊、極敏感、暗處黑白視覺（視紫質）。<b>錐細胞</b>：約 600 萬、集中在中央小窩、亮處的色覺與精細視覺。",c:"10.7"},
 rhodopsin:{t:"視紫質 rhodopsin",d:"桿細胞的感光色素＝視蛋白＋11-順式視網醛（來自維生素 A）；光使其漂白並啟動視覺訊號。",c:"10.7"},
 retinal:{t:"視網醛 retinal",d:"維生素 A 的醛類形式，是感光色素的發色團；11-順式照光後變成全反式。",c:"10.7；營養學"},
 transducin:{t:"轉導素 transducin",d:"視紫質活化的 G 蛋白，進而活化磷酸二酯酶分解 cGMP，使鈉通道關閉。",c:"10.7"},
 darkadapt:{t:"暗適應、光適應 dark / light adaptation",d:"<b>暗適應</b>：進入暗處後視紫質逐漸再生，敏感度增加約 10 萬倍以上（20–30 分鐘）。<b>光適應</b>：進入亮處後視紫質漂白，敏感度下降（較快）。",c:"10.7"},
 nightblind:{t:"夜盲症 night blindness",d:"維生素 A 缺乏使視紫質再生不足，在暗處或黃昏看不清楚；是維生素 A 缺乏最早的症狀之一。",c:"10.7；營養學"},
 fovea:{t:"中央小窩、黃斑部 fovea centralis / macula lutea",d:"<b>黃斑部</b>是視網膜中央的黃色區域（含葉黃素、玉米黃素），其中心的<b>中央小窩</b>只有錐細胞，是視覺最清晰處。",c:"10.7"},
 trichrom:{t:"三色理論 trichromatic theory",d:"三種錐細胞分別對藍、綠、紅光最敏感，腦依三者被活化的比例判斷顏色。",c:"10.7"},
 colorblind:{t:"色盲 color blindness",d:"缺少某種錐細胞或光視素異常；最常見的紅綠色盲為 X 性聯隱性遺傳，男性較多。",c:"10.7"},
 blindspot:{t:"盲點 blind spot（視神經盤）",d:"視神經離開眼球處，沒有感光細胞，所以看不到落在這裡的影像。",c:"10.7"},
 chiasma:{t:"視交叉 optic chiasma",d:"兩條視神經在腦下方的交會處，兩眼鼻側視網膜的纖維在此交叉到對側，使左視野送到右腦。",c:"10.8；第 11 章"},
 lgn:{t:"外側膝狀核 lateral geniculate nucleus",d:"視丘中負責轉送視覺訊號到枕葉視覺皮質的神經核。",c:"10.8"},
 visualcx:{t:"視覺皮質 visual cortex",d:"枕葉的視覺處理區；之後分腹側（往顳葉：是什麼）與背側（往頂葉：在哪裡、怎麼動）兩條路徑。",c:"10.8"}
});
