Object.assign(GL,{
 hormclass:{t:"激素的化學分類",d:"<b>胺類</b>（兒茶酚胺、褪黑激素、甲狀腺激素）、<b>胜肽與蛋白質</b>（胰島素、GH、ADH）、<b>醣蛋白</b>（FSH、LH、TSH）、<b>類固醇</b>（皮質醇、醛固酮、性激素）。",c:"11.1"},
 prohorm:{t:"激素原、前激素 prohormone / prehormone",d:"<b>激素原</b>：在分泌細胞內切割才成為激素（胰島素原、POMC）。<b>前激素</b>：分泌後要在標的組織轉換才有活性（T₄ → T₃、維生素 D 活化）。",c:"11.1"},
 synerg:{t:"協同、允許、拮抗作用",d:"<b>協同</b>：一起作用效果更大。<b>允許</b>：一個激素使組織對另一個更敏感（皮質醇對兒茶酚胺）。<b>拮抗</b>：作用相反（胰島素 vs 升糖素）。",c:"11.1"},
 permissive:{t:"允許作用 permissive effect",d:"某激素本身不直接產生效果，但讓組織對另一激素反應更好，常是增加受體數量。",e:"甲狀腺激素增加 β 受體，允許腎上腺素促進脂肪分解。",c:"11.1"},
 updown:{t:"上調、下調 up-regulation / down-regulation",d:"<b>上調</b>：受體增加、反應變敏感。<b>下調（脫敏）</b>：長期高濃度使受體減少、反應變差。",e:"持續給 GnRH 反而抑制 LH、FSH。",c:"11.1"},
 hre:{t:"激素反應元 hormone-response element",d:"DNA 上能被激素—受體複合物結合的特定序列，決定哪些基因被類固醇或甲狀腺激素調控。",c:"11.2"},
 rxr:{t:"視網醇 X 受體 RXR",d:"與甲狀腺激素受體、維生素 D 受體配對成異二聚體的核受體，其配體是維生素 A 的衍生物。",c:"11.2"},
 plc:{t:"磷脂酶 C phospholipase C",d:"被 G 蛋白活化後把膜磷脂分解成 IP₃ 與 DAG 的酵素；IP₃ 使內質網釋放 Ca²⁺。",c:"11.2；第 6 章"},
 tyrk:{t:"酪胺酸激酶受體 receptor tyrosine kinase",d:"本身具酵素活性的膜受體：激素結合後自身磷酸化，再磷酸化細胞內蛋白質。胰島素、生長因子的受體屬此類。",c:"11.2"},
 pituitary:{t:"腦垂腺 pituitary gland",d:"掛在下視丘下方的「主腺體」：<b>前葉</b>（GH、TSH、ACTH、FSH、LH、PRL）、<b>後葉</b>（ADH、催產素）。",c:"11.3"},
 antpit:{t:"腦垂腺前葉、後葉",d:"<b>前葉</b>是真正的腺體，受下視丘經門脈系統送來的釋放／抑制激素控制。<b>後葉</b>是下視丘的延伸，釋放下視丘神經元做好的 ADH 與催產素。",c:"11.3"},
 gh:{t:"生長激素 growth hormone（GH）",d:"腦垂腺前葉分泌：經肝臟產生 IGF-1 促進骨骼與組織生長；直接促進蛋白質合成、脂肪分解、升高血糖。深睡時分泌最多。",c:"11.3；第 19 章"},
 tsh:{t:"甲狀腺刺激素 TSH",d:"腦垂腺前葉分泌，促進甲狀腺激素合成與分泌及甲狀腺生長；受 TRH 促進、受甲狀腺激素負回饋抑制。",c:"11.3、11.5"},
 acth:{t:"促腎上腺皮質激素 ACTH",d:"腦垂腺前葉分泌，促進腎上腺皮質分泌皮質醇；受 CRH 促進、皮質醇負回饋抑制。",c:"11.3、11.4"},
 fsh:{t:"濾泡刺激素 FSH",d:"腦垂腺前葉分泌的促性腺激素：女性促進濾泡發育與雌激素，男性促進精子生成。",c:"11.3；第 20 章"},
 prl:{t:"泌乳素（催乳素）prolactin（PRL）",d:"腦垂腺前葉分泌，促進乳腺<b>製造乳汁</b>；受多巴胺（PIH）抑制。注意不是催產素。",c:"11.3；第 20 章"},
 gonadotropin:{t:"促性腺激素 gonadotropins",d:"FSH 與 LH 的合稱，作用在卵巢與睪丸。",c:"11.3；第 20 章"},
 di:{t:"尿崩症 diabetes insipidus",d:"ADH 缺乏（或腎臟對 ADH 無反應），腎臟無法回收水，排出大量稀尿、口渴。與糖尿病無關。",n:"insipidus＝無味，尿不甜。",c:"11.3；第 17 章"},
 portal:{t:"下視丘—垂體門脈系統 hypothalamo-hypophyseal portal system",d:"連接下視丘與腦垂腺前葉的兩套微血管，讓下視丘激素不經全身循環、直接送到前葉。",c:"11.3"},
 relhorm:{t:"釋放激素、抑制激素 releasing / inhibiting hormones",d:"下視丘分泌、調控前葉的激素：TRH、CRH、GnRH、GHRH（促進）；生長抑素、多巴胺（抑制）。",c:"11.3"},
 trh:{t:"TRH、CRH、GnRH、GHRH",d:"下視丘釋放激素：<b>TRH</b>→TSH；<b>CRH</b>→ACTH；<b>GnRH</b>→FSH、LH（需脈衝式）；<b>GHRH</b>→GH。",c:"11.3"},
 somatostatin:{t:"生長抑素 somatostatin",d:"下視丘分泌時抑制 GH（與 TSH）；胰島 δ 細胞與腸道也分泌，局部抑制胰島素、升糖素與消化活動。",c:"11.3、11.6"},
 axis:{t:"下視丘—腦垂腺—標的腺體軸 axis",d:"三層調控：下視丘 → 腦垂腺前葉 → 標的腺體；標的激素回頭負回饋抑制上兩層。如 HPA（腎上腺）、HPT（甲狀腺）、HPG（性腺）軸。",c:"11.3"},
 igf:{t:"類胰島素生長因子 IGF-1（體介素）",d:"肝臟受 GH 刺激產生，促進骨骼生長板軟骨細胞分裂與組織生長；營養不良時降低。",c:"11.3"},
 acromegaly:{t:"肢端肥大症、巨人症、侏儒症",d:"GH 過多：兒童 → <b>巨人症</b>；成人 → <b>肢端肥大症</b>（手腳下巴增厚）。兒童 GH 不足 → <b>侏儒症</b>。",c:"11.3"},
 adcortex:{t:"腎上腺皮質 adrenal cortex",d:"腎上腺外層，分泌類固醇：球狀帶（醛固酮）、束狀帶（皮質醇）、網狀帶（雄性素）——鹽、糖、性。",c:"11.4"},
 aldosterone:{t:"醛固酮 aldosterone",d:"礦物皮質素：使腎臟再吸收 Na⁺、分泌 K⁺ 與 H⁺，增加血容積與血壓；受腎素—血管收縮素系統與高血鉀刺激。",c:"11.4；第 14、17 章"},
 cortisol:{t:"皮質醇 cortisol",d:"糖皮質素：促進糖質新生（升血糖）、分解蛋白質、抗發炎、抑制免疫、允許兒茶酚胺作用；受 ACTH 控制，清晨最高。",c:"11.4；第 19 章"},
 mineralo:{t:"礦物皮質素、糖皮質素 mineralocorticoid / glucocorticoid",d:"<b>礦物皮質素</b>（醛固酮）調節礦物質（Na⁺、K⁺）。<b>糖皮質素</b>（皮質醇）調節葡萄糖代謝。",c:"11.4"},
 cushing:{t:"庫欣氏症候群 Cushing's syndrome",d:"皮質醇過多：月亮臉、水牛肩、中央肥胖、高血糖、高血壓、肌肉無力、骨質疏鬆；最常見原因是長期服用類固醇。",c:"11.4"},
 addison:{t:"愛迪生氏症 Addison's disease",d:"腎上腺皮質功能不足：皮質醇與醛固酮都缺乏 → 低血糖、低血壓、低血鈉、高血鉀、疲倦；ACTH 升高使皮膚色素沉著。",c:"11.4"},
 pheo:{t:"嗜鉻細胞瘤 pheochromocytoma",d:"腎上腺髓質的腫瘤，分泌過多兒茶酚胺，造成陣發性高血壓、心悸、頭痛、冒汗。",c:"11.4"},
 gas:{t:"一般適應症候群 general adaptation syndrome",d:"塞利提出的壓力反應三期：警覺期（交感—腎上腺髓質）→ 抵抗期（皮質醇）→ 衰竭期。",c:"11.4"},
 thyroid:{t:"甲狀腺 thyroid gland",d:"頸部氣管前方的蝴蝶形腺體，濾泡細胞分泌 T₄、T₃，濾泡旁細胞（C 細胞）分泌降鈣素。",c:"11.5"},
 t4:{t:"甲狀腺素 T₄、T₃",d:"<b>T₄</b>（4 個碘）占分泌的約 90%；<b>T₃</b>（3 個碘）活性較強，多由 T₄ 在組織中脫碘而來（脫碘酶含硒）。",c:"11.5"},
 thyroglob:{t:"甲狀腺球蛋白 thyroglobulin",d:"甲狀腺濾泡膠體中的大型蛋白質，其酪胺酸被碘化後形成 T₄、T₃，儲存在濾泡中。",c:"11.5"},
 bmr:{t:"基礎代謝率 basal metabolic rate（BMR）",d:"清醒、安靜、空腹、舒適溫度下維持生命所需的能量消耗；甲狀腺激素是主要調節因子。",c:"11.5；第 19 章"},
 hypothyroid:{t:"甲狀腺功能低下、亢進",d:"<b>低下</b>（橋本氏、碘缺乏）：怕冷、體重增加、心跳慢、疲倦、黏液水腫。<b>亢進</b>（葛瑞夫茲）：怕熱、體重減輕、心悸、手抖、突眼。",c:"11.5"},
 goiter:{t:"甲狀腺腫 goiter",d:"甲狀腺腫大。碘缺乏時 T₄ 不足、TSH 增加而長大（地方性甲狀腺腫）；葛瑞夫茲病由抗體刺激而長大。",c:"11.5"},
 cretinism:{t:"呆小症 cretinism",d:"嬰幼兒甲狀腺激素不足造成的生長遲緩與智能障礙；新生兒篩檢可早期發現治療。",c:"11.5"},
 graves:{t:"葛瑞夫茲病 Graves' disease",d:"自體抗體模仿 TSH 持續刺激甲狀腺，造成甲狀腺亢進與腫大、突眼；TSH 本身反而很低。",c:"11.5"},
 hashimoto:{t:"橋本氏甲狀腺炎 Hashimoto's thyroiditis",d:"自體免疫破壞甲狀腺，是甲狀腺功能低下最常見的原因（碘充足地區）。",c:"11.5"},
 pth:{t:"副甲狀腺素 parathyroid hormone（PTH）",d:"血鈣下降時由副甲狀腺分泌：骨骼釋放鈣、腎臟保鈣排磷、活化維生素 D 使腸道吸收鈣 → 血鈣上升。",c:"11.5；第 19 章"},
 calcitonin:{t:"降鈣素 calcitonin",d:"甲狀腺濾泡旁細胞（C 細胞）在血鈣升高時分泌，抑制蝕骨細胞、降低血鈣；成人作用小。",c:"11.5"},
 osteoclast:{t:"蝕骨細胞、造骨細胞 osteoclast / osteoblast",d:"<b>蝕骨細胞</b>（破骨細胞）分解骨基質、釋放鈣磷；<b>造骨細胞</b>製造新骨。兩者平衡進行骨骼重塑。",c:"11.5；第 19 章"},
 calcitriol:{t:"活性維生素 D（骨化三醇）1,25-(OH)₂D₃",d:"維生素 D 在肝臟（25-羥化）與腎臟（1α-羥化，PTH 促進）兩次活化後的形式，促進腸道吸收鈣磷。",c:"11.5；第 19 章"},
 islets2:{t:"胰島的細胞",d:"<b>β 細胞</b>（約 60–70%）：胰島素；<b>α 細胞</b>：升糖素；<b>δ 細胞</b>：生長抑素；另有 PP 細胞。",c:"11.6"},
 dm:{t:"第 1 型、第 2 型糖尿病",d:"<b>第 1 型</b>：自體免疫破壞 β 細胞，胰島素缺乏，需注射胰島素，易酮酸中毒。<b>第 2 型</b>：胰島素阻抗為主（占 90% 以上），與肥胖、缺乏運動相關。",c:"11.6；第 19 章"},
 incretin:{t:"腸泌素 incretins",d:"進食時腸道分泌、在血糖上升前就促進胰島素分泌的激素：GIP 與 GLP-1。GLP-1 類似物是新型降血糖與減重藥物。",c:"11.6；第 18、19 章"},
 thymus:{t:"胸腺 thymus",d:"胸骨後方的器官，T 淋巴球在此成熟；兒童期最大，青春期後逐漸萎縮成脂肪。",c:"11.6；第 15 章"},
 hcg:{t:"人類絨毛膜促性腺激素 hCG",d:"胚胎與胎盤分泌，維持黃體繼續分泌黃體素；是驗孕試劑檢測的對象。",c:"11.6；第 20 章"},
 hpl:{t:"人類胎盤催乳素 hPL",d:"胎盤分泌，使母體產生胰島素阻抗，把葡萄糖留給胎兒；與妊娠糖尿病有關。",c:"11.6；第 20 章"},
 anp:{t:"心房利鈉胜肽 ANP",d:"心房被血容積撐開時分泌，促進腎臟排鈉排水、擴張血管、降低血壓；作用與醛固酮相反。",c:"11.6；第 14 章"},
 epo:{t:"紅血球生成素 erythropoietin（EPO）",d:"腎臟在缺氧時分泌，刺激骨髓製造紅血球；腎衰竭時不足造成貧血。",c:"11.6；第 13 章"},
 leptin:{t:"瘦體素 leptin",d:"脂肪細胞分泌，告訴下視丘體脂存量，抑制食慾、增加能量消耗；肥胖者常有瘦體素阻抗。",n:"希臘文 leptos＝瘦。",c:"11.6；第 19 章"},
 ghrelin:{t:"飢餓素 ghrelin",d:"空腹時胃分泌，刺激下視丘增加食慾，也促進 GH 分泌；進食後下降。",c:"11.6；第 18、19 章"},
 growthf:{t:"生長因子 growth factors",d:"以旁泌或自泌方式促進特定細胞分裂與生長的蛋白質，如 NGF、EGF、PDGF、IGF。",c:"11.7"},
 cytokine:{t:"細胞激素 cytokines",d:"免疫細胞等分泌的訊號蛋白（如介白素），調節免疫與發炎反應。",c:"11.7；第 15 章"},
 endothelin:{t:"內皮素 endothelin",d:"血管內皮細胞分泌的強力血管收縮物質，與一氧化氮共同調節局部血流。",c:"11.7；第 14 章"},
 cox:{t:"環氧化酶 cyclooxygenase（COX）",d:"把花生四烯酸轉成前列腺素與血栓素的酵素。COX-1 常態存在，COX-2 在發炎時被誘導；阿斯匹靈等 NSAIDs 抑制它。",c:"11.7"},
 thromboxane:{t:"血栓素 thromboxane A₂",d:"血小板以 COX 製造的類二十碳酸，促進血小板凝集與血管收縮；低劑量阿斯匹靈抑制它。",c:"11.7；第 13 章"},
 prostacyclin:{t:"前列環素 prostacyclin",d:"血管內皮製造的類二十碳酸，抑制血小板凝集、擴張血管，與血栓素作用相反。",c:"11.7"},
 leukotriene:{t:"白三烯素 leukotrienes",d:"花生四烯酸經脂氧化酶產生，引起支氣管收縮與發炎，與氣喘、過敏有關。",c:"11.7"},
 nsaid:{t:"非類固醇抗發炎藥 NSAIDs",d:"抑制 COX 的藥物（阿斯匹靈、布洛芬等）：止痛、退燒、消炎；副作用為胃潰瘍、出血、腎功能影響。",c:"11.7"},
 eicos:{t:"類二十碳酸 eicosanoids",d:"由 20 碳脂肪酸（花生四烯酸、EPA）衍生的局部訊號分子：前列腺素、血栓素、前列環素、白三烯素。",c:"11.7；第 2 章"}
});
