Object.assign(GL,{
 fascicle:{t:"肌束 fascicle",d:"一束被肌束膜包住的肌纖維；許多肌束組成一塊肌肉。",c:"12.1"},
 musfiber:{t:"肌纖維 muscle fiber",d:"一個骨骼肌細胞：又長又細、<b>多核</b>（由許多肌母細胞融合而成），內含大量肌原纖維。",c:"12.1"},
 sarcolemma:{t:"肌漿膜 sarcolemma",d:"肌纖維的細胞膜；能傳導動作電位，並向內凹成 T 小管。",n:"sarco-＝肉，lemma＝外殼。",c:"12.1"},
 myofibril:{t:"肌原纖維 myofibril",d:"肌纖維內一條條平行的收縮構造，由一節節肌節串成。",c:"12.1"},
 sarcomere:{t:"肌節 sarcomere",d:"從一條 Z 線到下一條 Z 線，是肌肉收縮的最小單位，內有粗、細肌絲交錯排列。",w:"肌原纖維上",f:"縮短 → 整條肌肉縮短",c:"12.1"},
 thickf:{t:"粗肌絲、細肌絲 thick / thin filaments",d:"<b>粗肌絲</b>：肌凝蛋白，在肌節中央、固定於 M 線。<b>細肌絲</b>：肌動蛋白＋旋轉肌球素＋肌鈣蛋白，固定於 Z 線。",c:"12.1"},
 myosin:{t:"肌凝蛋白 myosin",d:"組成粗肌絲的馬達蛋白，頭部能結合肌動蛋白並水解 ATP，產生拉力。",c:"12.1–12.2"},
 actin:{t:"肌動蛋白 actin",d:"組成細肌絲的球狀蛋白串成的長鏈，上有供肌凝蛋白結合的位置。",c:"12.1–12.2"},
 aband:{t:"A 帶、I 帶、H 帶",d:"<b>A 帶</b>（暗）：粗肌絲全長，收縮時不變。<b>I 帶</b>（亮）：只有細肌絲，Z 線在中央，收縮時變短。<b>H 帶</b>：A 帶中央只有粗肌絲的部分，收縮時變短。",m:"A＝Anisotropic（暗），I＝Isotropic（亮）；收縮時「A 不變」。",c:"12.1"},
 zline:{t:"Z 線、M 線",d:"<b>Z 線</b>：細肌絲的固定處，肌節的邊界。<b>M 線</b>：肌節中央，粗肌絲的固定處。",c:"12.1"},
 titin:{t:"肌聯蛋白 titin",d:"人體最大的蛋白質之一，從 Z 線延伸到 M 線，像彈簧提供肌節彈性並固定粗肌絲位置。",c:"12.1"},
 satellite:{t:"衛星細胞 satellite cells",d:"位於肌纖維旁的肌肉幹細胞，受損或阻力訓練時活化、融入肌纖維，負責修復與肥大。",c:"12.1、12.4"},
 motorunit:{t:"運動單位 motor unit",d:"一個運動神經元加上它支配的所有肌纖維；神經元放電時這些纖維同時收縮。",e:"眼肌單位小（精細），大腿肌單位大（有力）。",c:"12.1"},
 recruit:{t:"徵召、大小原則 recruitment / size principle",d:"增加力量時神經系統動員更多運動單位，先小（慢縮、耐疲勞）後大（快縮、力量大）。",c:"12.1"},
 sliding:{t:"滑動肌絲理論 sliding filament theory",d:"收縮時肌絲本身不變短，而是細肌絲滑向肌節中央，使 Z 線靠近。",e:"兩把梳子的齒插得更深。",c:"12.2"},
 crossbridge:{t:"橫橋 cross bridge",d:"肌凝蛋白頭部與肌動蛋白結合形成的連接；反覆結合、擺動、脫離產生拉力。",c:"12.2"},
 powerstroke:{t:"動力衝程 power stroke",d:"肌凝蛋白頭部釋放 Pi 後擺動，把細肌絲拉向肌節中央的一步。",c:"12.2"},
 rigor:{t:"屍僵 rigor mortis",d:"死後 ATP 耗盡，肌凝蛋白頭部無法與肌動蛋白分離，肌肉僵硬；蛋白質分解後才消失。",c:"12.2"},
 tropomyosin:{t:"旋轉肌球素 tropomyosin",d:"沿細肌絲排列的細長蛋白，放鬆時蓋住肌動蛋白上的結合位，阻止橫橋形成。",c:"12.2"},
 troponin:{t:"肌鈣蛋白 troponin",d:"附在旋轉肌球素上、能結合 Ca²⁺ 的蛋白；結合 Ca²⁺ 後把旋轉肌球素移開，開啟收縮。骨骼肌與心肌才有。",n:"tropo- 加上能結合鈣的特性，中文譯為「肌鈣」蛋白。",c:"12.2"},
 ecc:{t:"興奮—收縮偶聯 excitation-contraction coupling",d:"從肌漿膜動作電位到肌漿網釋放 Ca²⁺、引起收縮的連結過程。",c:"12.2"},
 ttubule:{t:"橫小管（T 小管）transverse tubules",d:"肌漿膜向細胞內凹入的管道，把動作電位帶到肌纖維深處，緊貼肌漿網。",c:"12.2"},
 sr:{t:"肌漿網 sarcoplasmic reticulum",d:"肌纖維中特化的平滑內質網，包圍肌原纖維，儲存並釋放 Ca²⁺，再以鈣幫浦回收。",c:"12.2"},
 ryr:{t:"DHP 受體、ryanodine 受體",d:"<b>DHP 受體</b>：T 小管上的電壓感測器（L 型鈣通道）。<b>Ryanodine 受體</b>：肌漿網上的 Ca²⁺ 釋放通道，被 DHP 受體打開。",c:"12.2"},
 serca:{t:"肌漿網鈣幫浦 SERCA",d:"肌漿網膜上的 Ca²⁺-ATPase，耗 ATP 把 Ca²⁺ 打回肌漿網，使肌肉放鬆。",c:"12.2"},
 twitch:{t:"單一收縮 twitch",d:"一個動作電位引起的一次快速收縮與放鬆，含潛伏期、收縮期、放鬆期。",c:"12.3"},
 summation:{t:"加成 summation",d:"前一次收縮尚未放鬆完，下一個刺激又來，張力疊加變大。",c:"12.3"},
 tetanus:{t:"強直 tetanus",d:"高頻刺激使收縮融合成持續收縮：不完全強直（有起伏）→ 完全強直（平滑最大）。與破傷風同名但意義不同。",c:"12.3"},
 treppe:{t:"階梯現象 treppe",d:"休息後的肌肉在同強度反覆刺激下，前幾次收縮逐漸增強，類似暖身效果。",n:"德文 Treppe＝樓梯。",c:"12.3"},
 isotonic:{t:"等張收縮 isotonic contraction",d:"肌肉長度改變、張力大致不變的收縮；分<b>向心</b>（縮短）與<b>離心</b>（被拉長）。",c:"12.3"},
 isometric:{t:"等長收縮 isometric contraction",d:"肌肉張力增加但長度不變，如推牆、維持姿勢、提著重物不動。",n:"iso＝相同，metric＝長度。",c:"12.3"},
 eccentric:{t:"向心、離心收縮 concentric / eccentric",d:"<b>向心</b>：用力時縮短（舉起）。<b>離心</b>：用力時被拉長，當煞車（放下、下樓梯），較易造成肌肉微損傷與延遲性痠痛。",c:"12.3"},
 doms:{t:"延遲性肌肉痠痛 DOMS",d:"運動（特別是離心收縮）後 24–72 小時出現的痠痛，來自肌纖維微小損傷與發炎修復，不是乳酸堆積。",c:"12.3"},
 sec:{t:"串聯彈性成分 series-elastic component",d:"肌腱、結締組織與肌聯蛋白等彈性構造，收縮時先被拉緊才傳力，放鬆時回彈。",c:"12.3"},
 lengthtension:{t:"長度—張力關係 length-tension relationship",d:"肌節在靜止長度附近，粗細肌絲重疊最適當，形成最多橫橋，張力最大；太長或太短都減弱。",c:"12.3；第 14 章"},
 mtension:{t:"張力（肌肉）muscle tension",d:"肌肉收縮時對附著處產生的拉力。（第 6 章的「張力性」tonicity 是溶液對細胞體積的影響，意思不同。）",c:"12.3"},
 musctone:{t:"肌張力 muscle tone",d:"靜止時肌肉維持的輕微收縮狀態，由牽張反射與 γ 運動神經元活動維持。",c:"12.5"},
 cp:{t:"磷酸肌酸 creatine phosphate",d:"肌肉中的高能磷酸儲存庫，經肌酸激酶把磷酸轉給 ADP，數秒內補回 ATP（約撐 10 秒爆發運動）。",c:"12.4；第 5 章"},
 ck:{t:"肌酸激酶 creatine kinase（CK）",d:"催化磷酸肌酸＋ADP ⇌ 肌酸＋ATP 的酵素；肌肉或心肌受損時血中 CK 升高。",c:"12.4"},
 vo2max:{t:"最大攝氧量 V̇O₂max",d:"每分鐘能利用的最大氧氣量，代表有氧能力；受心輸出量與肌肉粒線體決定，耐力訓練可提高。",c:"12.4"},
 lt:{t:"乳酸閾值 lactate threshold",d:"運動強度增加到血中乳酸開始明顯上升的點（以 V̇O₂max 的百分比表示），耐力訓練可提高。",c:"12.4"},
 epoc:{t:"運動後過耗氧量 EPOC",d:"運動後仍維持較高耗氧，用以補回磷酸肌酸與氧儲存、清除乳酸、恢復體溫與心跳；舊稱氧債。",c:"12.4；第 5 章"},
 slowfiber:{t:"慢縮、快縮肌纖維",d:"<b>第 I 型慢縮（紅肌）</b>：粒線體、肌紅素、微血管多，有氧、耐疲勞，姿勢肌。<b>第 IIx 型快縮（白肌）</b>：力量大、肝醣多、粒線體少、無氧、易疲勞。<b>IIa</b> 介於中間。",m:"紅肌像馬拉松、白肌像短跑。",c:"12.4"},
 myoglobin:{t:"肌紅素 myoglobin",d:"肌肉中含鐵、能儲存氧的蛋白質（只有一條鏈），幫助氧擴散到粒線體，使慢縮肌呈紅色。",c:"12.4；第 16 章"},
 fatigue:{t:"肌肉疲勞 muscle fatigue",d:"持續使用後力量下降：短時以 Pi、K⁺ 累積為主；長時以肝醣耗盡為主；也有中樞疲勞。",c:"12.4"},
 hypertrophy:{t:"肥大、萎縮 hypertrophy / atrophy",d:"<b>肥大</b>：阻力訓練使肌纖維增粗（收縮蛋白增加）。<b>萎縮</b>：不使用、臥床使肌纖維變細。",c:"12.4"},
 sarcopenia:{t:"肌少症 sarcopenia",d:"隨年齡肌肉量與力量下降，增加跌倒與失能；建議足夠蛋白質、維生素 D 與阻力運動。",c:"12.4"},
 dystrophy:{t:"肌肉失養症 muscular dystrophy",d:"杜興氏型為 X 染色體上 dystrophin 基因缺陷，肌纖維反覆受損、被脂肪與結締組織取代，多見於男孩。",c:"12.4"},
 spindle:{t:"肌梭 muscle spindle",d:"肌腹中與肌纖維平行的牽張感受器，偵測長度與拉長速度，引起牽張反射。",c:"12.5"},
 gto:{t:"高爾基肌腱器 Golgi tendon organ",d:"在肌腱與肌肉交界處，偵測張力；張力過大時抑制同一肌肉，保護肌腱。",c:"12.5"},
 intrafusal:{t:"梭內、梭外肌纖維 intrafusal / extrafusal",d:"<b>梭內</b>：肌梭裡特化的感覺用肌纖維（γ 支配）。<b>梭外</b>：一般產生力量的肌纖維（α 支配）。",n:"fusus＝紡錘。",c:"12.5"},
 alphagamma:{t:"α、γ 運動神經元",d:"<b>α</b>：支配梭外肌纖維，產生力量。<b>γ</b>：支配梭內肌纖維兩端，使肌梭在肌肉縮短時仍保持敏感；兩者常同時活化（α–γ 共同活化）。",c:"12.5"},
 stretchreflex:{t:"牽張反射 stretch reflex",d:"肌肉被拉長 → 肌梭 → 感覺神經元直接興奮同一肌肉的 α 運動神經元（單突觸）→ 收縮。膝跳反射是代表。",c:"12.5；第 8 章"},
 recinhib:{t:"交互抑制 reciprocal inhibition",d:"一條肌肉被反射興奮時，經抑制性聯絡神經元同時放鬆其拮抗肌。",c:"12.5"},
 umn:{t:"上、下運動神經元 upper / lower motor neuron",d:"<b>下運動神經元</b>：脊髓與腦幹直接支配肌肉者。<b>上運動神經元</b>：大腦與腦幹下行控制者。上受損 → 痙攣、反射亢進；下受損 → 弛緩、萎縮、反射消失。",c:"12.5"},
 intercal:{t:"間盤 intercalated discs",d:"心肌細胞間的連接，含胞橋小體（抗拉扯）與間隙接合（傳電），使心肌成為功能合體。",c:"12.6；第 13 章"},
 syncytium:{t:"功能合體 functional syncytium",d:"許多細胞以間隙接合相連，電訊號直接傳遞，像一個大細胞一樣同步收縮（心房、心室、單一單元平滑肌）。",c:"12.6"},
 cicr:{t:"鈣誘發鈣釋放 calcium-induced calcium release",d:"心肌中，Ca²⁺ 先由細胞外經 L 型通道流入，觸發肌漿網釋放更多 Ca²⁺。",c:"12.6；第 13 章"},
 densebody:{t:"緻密體 dense bodies",d:"平滑肌細胞內固定細肌絲的構造，功能相當於骨骼肌的 Z 線。",c:"12.6"},
 calmodulin:{t:"鈣調蛋白 calmodulin",d:"廣泛存在的 Ca²⁺ 結合蛋白；在平滑肌中結合 Ca²⁺ 後活化肌凝蛋白輕鏈激酶。",c:"12.6；第 6、11 章"},
 mlck:{t:"肌凝蛋白輕鏈激酶 MLCK",d:"被 Ca²⁺–鈣調蛋白活化，把平滑肌肌凝蛋白磷酸化，使其能形成橫橋；肌凝蛋白磷酸酶則使其放鬆。",c:"12.6"},
 latch:{t:"門閂狀態 latch state",d:"平滑肌能以很少的 ATP 長時間維持張力的狀態，適合血管與括約肌。",c:"12.6"},
 singleunit:{t:"單一單元、多單元平滑肌",d:"<b>單一單元</b>：間隙接合多、同步收縮、有自發節律、受伸展刺激（消化道、子宮、小血管）。<b>多單元</b>：每條纖維由神經個別支配、精細控制（虹膜、睫狀肌、豎毛肌、大氣道、大動脈、輸精管）。",m:"多單元＝「眼、毛、大管子」。",c:"12.6"}
});
