Object.assign(GL,{
 co:{t:"心輸出量 cardiac output",d:"每分鐘一個心室打出的血量＝心率 × 心搏量；靜止約 5 L/分，劇烈運動可達 20–35 L/分。",c:"14.1"},
 hr:{t:"心率 heart rate",d:"每分鐘心跳次數；竇房結本身約 100，靜止時因迷走神經抑制約 70；交感與腎上腺素使其加快。",c:"14.1"},
 preload:{t:"前負荷、後負荷 preload / afterload",d:"<b>前負荷</b>：心舒期末容積，心肌被撐開的程度。<b>後負荷</b>：心室射血要克服的動脈壓與周邊阻力。",c:"14.1"},
 contractility:{t:"收縮力 contractility",d:"在相同心舒期末容積下心肌收縮的力量；交感神經與腎上腺素經 β₁、cAMP 使 Ca²⁺ 增加而增強（正變力作用）。",c:"14.1"},
 inotropic:{t:"變力作用、變時作用",d:"<b>變力</b>（inotropic）：改變收縮力。<b>變時</b>（chronotropic）：改變心率。交感兩者都是正向。",c:"14.1"},
 frankstarling:{t:"法蘭克—史達林定律 Frank-Starling law",d:"回流越多（EDV↑），心肌被拉長越多，收縮越強、心搏量越大；心臟的內在調節，使左右心室輸出相等。",e:"橡皮筋拉得越開，彈回越有力（在一定範圍內）。",c:"14.1"},
 tpr:{t:"總周邊阻力 total peripheral resistance",d:"全身血管對血流阻力的總和，主要由小動脈口徑決定；平均動脈壓 ≈ 心輸出量 × 總周邊阻力。",c:"14.1、14.3"},
 venreturn:{t:"靜脈回流 venous return",d:"每分鐘回到右心房的血量，決定心舒期末容積；靠靜脈收縮、骨骼肌幫浦、呼吸幫浦與血容積。",c:"14.1"},
 starlingf:{t:"史達林力 Starling forces",d:"決定微血管與組織間液體流動的力量：微血管靜水壓（推出）與血漿膠體滲透壓（拉回）。動脈端淨濾出、靜脈端淨吸回。",c:"14.2"},
 oncotic:{t:"膠體滲透壓 colloid osmotic pressure",d:"留在血管內的蛋白質（主要是白蛋白）產生的滲透壓，約 25 mmHg，把水拉回血管。",c:"14.2"},
 hydrostatic:{t:"靜水壓 hydrostatic pressure",d:"液體本身對管壁的壓力；在微血管就是血壓，把液體推出血管。",c:"14.2"},
 vasopressin:{t:"血管加壓素 vasopressin",d:"ADH 的另一個名字：高濃度時使血管收縮，故名。",c:"14.2、14.3"},
 renin:{t:"腎素 renin",d:"腎臟近腎絲球細胞在血壓或血量下降、交感興奮時分泌的酵素，把血管收縮素原切成血管收縮素 I。",c:"14.2；第 17 章"},
 jgcell:{t:"近腎絲球細胞 juxtaglomerular cells",d:"腎臟入球小動脈壁上的特化平滑肌細胞，感受血壓並分泌腎素。",c:"14.2；第 17 章"},
 angiotensin:{t:"血管收縮素 angiotensin",d:"血管收縮素原（肝）→ I（腎素）→ II（ACE）。<b>血管收縮素 II</b>：收縮小動脈、刺激醛固酮、口渴與 ADH。",c:"14.2"},
 ace:{t:"血管收縮素轉化酶 ACE",d:"主要在肺微血管內皮，把血管收縮素 I 轉成 II，也分解緩激肽；ACE 抑制劑（-pril）用來降血壓。",c:"14.2、14.7"},
 raas:{t:"腎素—血管收縮素—醛固酮系統 RAAS",d:"血壓↓ → 腎素 → 血管收縮素 II → 血管收縮＋醛固酮（保鈉保水）＋口渴與 ADH → 血壓回升。",c:"14.2"},
 arb:{t:"ACE 抑制劑、ARB",d:"降血壓藥：<b>ACE 抑制劑</b>（-pril）阻止血管收縮素 II 生成；<b>ARB</b>（-sartan）阻斷其受體。可能使血鉀上升。",c:"14.2、14.7"},
 natriuresis:{t:"利鈉作用 natriuresis",d:"腎臟排出鈉增加；ANP 與利尿劑都有此作用，水跟著鈉排出。",c:"14.2"},
 poiseuille:{t:"泊肅葉定律 Poiseuille's law",d:"流量與壓力差及半徑的四次方成正比，與管長及黏度成反比；半徑減半，流量剩 1/16。",c:"14.3"},
 viscosity:{t:"黏度 viscosity",d:"液體的濃稠程度；血液黏度主要由血比容決定，紅血球增多或脫水時增加。",c:"14.3"},
 vasocon:{t:"血管收縮、血管擴張 vasoconstriction / vasodilation",d:"血管平滑肌收縮使管徑變小、阻力增加；放鬆使管徑變大、阻力減少、血流增加。",c:"14.3"},
 autoreg:{t:"自動調節 autoregulation",d:"器官在血壓變動時自行維持穩定血流的能力，靠肌原性與代謝性機制；腦與腎最明顯。",c:"14.3、14.5"},
 myogenic:{t:"肌原性調節 myogenic regulation",d:"血管被血壓撐開時平滑肌反射性收縮、血壓降時放鬆，維持血流穩定。",c:"14.3"},
 metabolicreg:{t:"代謝性調節 metabolic regulation",d:"組織代謝旺盛時，O₂↓、CO₂、H⁺、K⁺、腺苷↑使局部小動脈擴張，血流增加。",c:"14.3"},
 hyperemia:{t:"充血 hyperemia",d:"局部血流增加：<b>主動充血</b>（運動時代謝增加）；<b>反應性充血</b>（血流被阻斷一段時間後恢復時血流大增）。",c:"14.3"},
 cgmp:{t:"cGMP（環鳥苷單磷酸）",d:"NO 活化鳥苷酸環化酶產生的第二傳訊者，使血管平滑肌放鬆；威而鋼抑制其分解。",c:"14.3；第 6 章"},
 coronary:{t:"冠狀動脈、冠狀循環 coronary circulation",d:"從主動脈根部發出供應心肌的動脈；心肌取氧率約 75%，需氧增加只能靠增加冠狀血流；左心室血流主要在心舒期。",c:"14.4；第 13 章"},
 avanast:{t:"動靜脈吻合 arteriovenous anastomoses",d:"皮膚（手、腳、耳、鼻）中讓血液繞過微血管直接從小動脈到小靜脈的通道，受交感控制，用於散熱或保熱。",c:"14.5"},
 bradykinin:{t:"緩激肽 bradykinin",d:"由血漿蛋白切出的胜肽，強力擴張血管、增加通透性並引起疼痛；被 ACE 分解（ACE 抑制劑的乾咳副作用與此有關）。",c:"14.5"},
 baro:{t:"壓力感受器 baroreceptors",d:"頸動脈竇（舌咽神經）與主動脈弓（迷走神經）壁上的伸張受器，偵測動脈血壓，傳到延腦。",c:"14.6"},
 baroreflex:{t:"壓力感受器反射 baroreceptor reflex",d:"血壓↓ → 感受器放電↓ → 交感↑、副交感↓ → 心率↑、血管收縮 → 血壓回升；反之亦然。短期負回饋。",c:"14.6"},
 carotidsinus:{t:"頸動脈竇、主動脈弓",d:"<b>頸動脈竇</b>：頸總動脈分叉處內頸動脈起端的膨大，有壓力感受器（舌咽神經）。<b>主動脈弓</b>：主動脈彎曲處（迷走神經）。注意化學感受器在頸動脈體與主動脈體（第 16 章）。",c:"14.6"},
 orthostatic:{t:"姿勢性（直立性）低血壓 orthostatic hypotension",d:"由躺或坐突然站起時血壓明顯下降而頭暈；壓力感受器反射不足、脫水、降壓藥、老年人常見。",c:"14.6"},
 valsalva:{t:"伐氏操作 Valsalva maneuver",d:"聲門關閉時用力呼氣 → 胸內壓↑ → 靜脈回流↓ → 血壓↓ → 心率反射性↑；放鬆後血壓回衝 → 心率↓。用力排便、舉重憋氣時發生。",c:"14.6（國考）"},
 bainbridge:{t:"班布里奇反射 Bainbridge reflex",d:"靜脈回流增加使心房被撐開時，心率反射性加快，把多出的血打出去。",c:"14.6"},
 korotkoff:{t:"柯氏音 sounds of Korotkoff",d:"以壓脈帶量血壓時，血液斷續通過被壓扁的動脈產生亂流的聲音：出現＝收縮壓，消失＝舒張壓。",c:"14.6"},
 sbp:{t:"收縮壓、舒張壓 systolic / diastolic pressure",d:"<b>收縮壓</b>：心室射血時動脈壓的最高值（約 120）。<b>舒張壓</b>：心舒期動脈壓的最低值（約 80）。",c:"14.6"},
 pulsepressure:{t:"脈壓 pulse pressure",d:"收縮壓－舒張壓（約 40 mmHg）；摸到的脈搏即由此產生；動脈硬化時變大。",c:"14.6"},
 map:{t:"平均動脈壓 mean arterial pressure",d:"≈ 舒張壓＋1/3 脈壓（120/80 約 93 mmHg），推動血液到各器官的平均壓力；≈ 心輸出量 × 總周邊阻力。",c:"14.6"},
 htn:{t:"高血壓 hypertension",d:"血壓持續偏高：簡報定義 ≥ 140/90 mmHg；台灣 2022 指引 ≥ 130/80 mmHg。九成以上為原發性；多無症狀卻損傷心、腦、腎與血管。",c:"14.7"},
 essentialhtn:{t:"原發性、續發性高血壓",d:"<b>原發性</b>（本態性，90–95%）：無單一原因，與鈉、肥胖、遺傳、腎臟、交感、RAAS 有關。<b>續發性</b>：有明確原因，如腎動脈狹窄、醛固酮過多、庫欣、嗜鉻細胞瘤。",c:"14.7"},
 dash:{t:"DASH 飲食",d:"Dietary Approaches to Stop Hypertension：多蔬果、全穀、低脂乳品、堅果豆類（富含鉀、鎂、鈣與纖維），少飽和脂肪、紅肉與甜食，配合減鈉。",c:"14.7"},
 diuretic:{t:"利尿劑 diuretics",d:"增加腎臟排鈉與排水的藥物，降低血容積與血壓；部分會使鉀流失（需注意低血鉀），保鉀型則可能使鉀升高。",c:"14.7；第 17 章"},
 betablocker:{t:"β 阻斷劑 β-blockers",d:"阻斷 β₁ 受體：減慢心率、降低收縮力與腎素分泌；用於高血壓、心絞痛、心衰竭、心律不整。",c:"14.7"},
 ccb:{t:"鈣通道阻斷劑 calcium channel blockers",d:"阻斷血管平滑肌（與心肌）的 L 型鈣通道，使血管放鬆擴張、降低血壓；葡萄柚汁會影響部分藥物的代謝。",c:"14.7"},
 lvh:{t:"左心室肥大 left ventricular hypertrophy",d:"長期高血壓使左心室後負荷增加，心肌增厚；初期代償，最後可能導致心衰竭與心律不整。",c:"14.7"},
 shock:{t:"循環性休克 circulatory shock",d:"組織灌流不足。類型：低血容積性、敗血性、過敏性、神經性、心因性。代償表現：心跳快、皮膚濕冷蒼白、尿少。",c:"14.7"},
 anaphylaxis:{t:"過敏性休克 anaphylactic shock",d:"嚴重過敏時大量組織胺使血管擴張、微血管漏液、支氣管收縮；需立即注射腎上腺素。",c:"14.7；第 15 章"},
 septic:{t:"敗血性休克 septic shock",d:"嚴重感染時細菌毒素引起大量 NO 與發炎物質，使血管廣泛擴張、通透性增加。",c:"14.7"},
 chf:{t:"鬱血性心衰竭 congestive heart failure",d:"心輸出量不足；腎臟保鈉保水使血量增加、靜脈壓升高：左心衰竭 → 肺水腫；右心衰竭 → 周邊水腫、肝腫大、頸靜脈怒張。",c:"14.7"},
 pulmedema:{t:"肺水腫 pulmonary edema",d:"肺微血管靜水壓升高（左心衰竭）或通透性增加，液體進入肺組織與肺泡，造成呼吸困難。",c:"14.7"},
 histamine:{t:"組織胺 histamine",d:"肥大細胞與嗜鹼性球釋放，使血管擴張、微血管通透性增加（紅腫）、支氣管收縮；胃中經 H₂ 受體促進胃酸。",c:"14.7；第 15、18 章"}
});
