Object.assign(GL,{
 ventilation:{t:"換氣 ventilation",d:"空氣進出肺的呼吸動作；與氣體交換（擴散）、細胞呼吸合稱呼吸。",c:"16.1"},
 alveoli:{t:"肺泡 alveoli",d:"約 3 億個小氣囊，總面積約 60–80 m²，壁極薄、外圍密布微血管，是氣體交換的地方。",c:"16.1"},
 alvcell:{t:"第一型、第二型肺泡細胞",d:"<b>第一型</b>：極扁平，占表面 95%，與微血管組成約 0.3 µm 的呼吸膜。<b>第二型</b>：分泌表面活性劑。",c:"16.1"},
 condzone:{t:"傳導區、呼吸區",d:"<b>傳導區</b>：鼻到終末細支氣管，送氣、加溫、加濕、過濾，不交換氣體。<b>呼吸區</b>：呼吸性細支氣管、肺泡管、肺泡，進行交換。",c:"16.1"},
 mucocil:{t:"黏液纖毛電扶梯 mucociliary escalator",d:"呼吸道杯狀細胞分泌黏液黏住微粒，纖毛把黏液往咽部推送；抽菸破壞纖毛。",c:"16.1"},
 pleura:{t:"胸膜、胸膜腔 pleura",d:"臟層胸膜覆蓋肺、壁層胸膜覆蓋胸壁，中間的胸膜腔只有一層液體，使肺貼著胸壁擴張。",c:"16.1"},
 pneumothorax:{t:"氣胸 pneumothorax",d:"空氣進入胸膜腔，胸膜內負壓消失，肺因彈性回縮而塌陷。",c:"16.1"},
 boyle:{t:"波以耳定律 Boyle's law",d:"溫度不變時，氣體的壓力與體積成反比；胸腔變大 → 肺內壓下降 → 空氣流入。",c:"16.2"},
 intrapulm:{t:"肺內壓、胸膜內壓",d:"<b>肺內壓</b>：肺泡內壓力，吸氣約 −3、呼氣約 +3 mmHg（相對大氣）。<b>胸膜內壓</b>：始終低於肺內壓（約 −3 到 −6），兩者差撐開肺。",c:"16.2"},
 compliance:{t:"順應性 compliance",d:"肺容易被撐開的程度；肺纖維化時下降，吸氣費力；肺氣腫時反而上升。",c:"16.2"},
 lungelastic:{t:"肺的彈性 elasticity",d:"肺被撐開後彈回的傾向，來自彈性蛋白纖維與表面張力；平靜呼氣靠它；肺氣腫時被破壞。",c:"16.2"},
 surfacetension:{t:"表面張力 surface tension",d:"肺泡內表面水分子互相吸引使肺泡傾向塌陷；依拉普拉斯定律（P＝2T/r）小肺泡更易塌陷。",c:"16.2"},
 surfactant:{t:"表面活性劑 surfactant",d:"第二型肺泡細胞分泌的磷脂質（主要 DPPC）與蛋白，降低表面張力、防止肺泡塌陷；胎兒約 28–32 週後足量分泌。",c:"16.2"},
 rds:{t:"呼吸窘迫症候群 respiratory distress syndrome",d:"早產兒缺乏表面活性劑，肺泡反覆塌陷、呼吸費力（透明膜疾病）；以人工表面活性劑與呼吸器治療，產前類固醇可預防。成人嚴重肺損傷時為 ARDS。",c:"16.2"},
 diaphragm:{t:"橫膈 diaphragm",d:"胸腔與腹腔之間的圓頂狀骨骼肌，收縮時下降擴大胸腔，是最主要的吸氣肌，由膈神經（C3–C5）支配。",c:"16.3"},
 intercostal:{t:"外肋間肌、內肋間肌",d:"<b>外肋間肌</b>：吸氣時上提肋骨。<b>內肋間肌</b>：用力呼氣時下降肋骨。",c:"16.3"},
 tidal:{t:"潮氣容積 tidal volume",d:"平靜時一次吸入或呼出的氣量，約 500 mL。",c:"16.3"},
 lungvol:{t:"肺容積與肺容量",d:"容積：TV 500、IRV 3,000、ERV 1,200、RV 1,200 mL。容量（相加）：VC＝IRV＋TV＋ERV；TLC＝VC＋RV；FRC＝ERV＋RV；IC＝TV＋IRV。",c:"16.3"},
 vc:{t:"肺活量 vital capacity",d:"盡力吸氣後盡力呼出的最大量＝IRV＋TV＋ERV，約 4,700 mL；限制性肺病時下降。",c:"16.3"},
 rv:{t:"殘氣容積 residual volume",d:"盡力呼氣後仍留在肺內的氣量（約 1,200 mL），肺量計測不到；肺氣腫時增加。",c:"16.3"},
 frc:{t:"功能肋餘容量 functional residual capacity",d:"平靜呼氣後留在肺內的量＝ERV＋RV（約 2,400 mL），使肺泡氣體組成保持穩定。",c:"16.3"},
 deadspace:{t:"死腔 dead space",d:"傳導區中不參與氣體交換的空間，約 150 mL；肺泡換氣量＝（潮氣容積－死腔）× 頻率。",c:"16.3"},
 fev1:{t:"FEV₁、FEV₁/FVC",d:"第一秒用力呼氣量與用力肺活量的比值，正常 ≥ 約 0.8；阻塞性肺病下降。",c:"16.3"},
 restrictive:{t:"限制性、阻塞性肺病",d:"<b>限制性</b>：肺無法充分擴張（纖維化），VC↓、FEV₁/FVC 正常。<b>阻塞性</b>：呼氣氣流受阻（氣喘、肺氣腫、慢性支氣管炎），FEV₁/FVC↓。",c:"16.3"},
 asthma:{t:"氣喘 asthma",d:"呼吸道慢性發炎，支氣管平滑肌對刺激過度反應而收縮（白三烯素、組織胺），通常可逆；以 β₂ 致效劑與吸入型類固醇治療。",c:"16.3"},
 emphysema:{t:"肺氣腫 emphysema",d:"肺泡壁被破壞、融合成大氣囊，交換面積減少、彈性喪失、呼氣時細支氣管塌陷；主因抽菸，屬阻塞性。",c:"16.3"},
 copd:{t:"慢性阻塞性肺病 COPD",d:"慢性支氣管炎與肺氣腫的合稱，呼氣氣流受阻、不完全可逆；病人常體重減輕、肌肉流失。",c:"16.3"},
 fibrosis:{t:"肺纖維化 pulmonary fibrosis",d:"肺組織被結締組織取代，順應性下降，屬限制性肺病；可由石綿、矽塵或不明原因造成。",c:"16.3"},
 partialp:{t:"分壓 partial pressure",d:"混合氣體中某一氣體貢獻的壓力＝總壓 × 該氣體比例（道耳吞定律）；氣體由高分壓擴散到低分壓。",c:"16.4"},
 dalton:{t:"道耳吞定律、亨利定律",d:"<b>道耳吞</b>：總壓＝各分壓之和。<b>亨利</b>：溶解在液體中的氣體量與分壓及溶解度成正比（CO₂ 溶解度約 O₂ 的 20 倍）。",c:"16.4"},
 abg:{t:"動脈血氣 arterial blood gas",d:"測量動脈血的 PO₂（約 100）、PCO₂（約 40）、pH（約 7.40）、HCO₃⁻（約 24）；評估換氣與酸鹼。",c:"16.4、16.8"},
 vq:{t:"通氣—灌流配合 V/Q",d:"肺泡換氣量與血流量的比值（約 0.8）；缺氧時肺小動脈收縮，把血導向通氣好的區域（與體循環相反）。",c:"16.4"},
 respcenter:{t:"呼吸中樞 respiratory centers",d:"延腦（背側呼吸群主吸氣、腹側呼吸群含節律產生者）自動產生節律；橋腦（呼吸調節中樞、長吸中樞）修飾。",c:"16.5"},
 centralchemo:{t:"中樞化學感受器 central chemoreceptors",d:"位於延腦腹側；血中 CO₂ 穿過血腦障壁在腦脊髓液生成 H⁺ 而刺激它；平常調控呼吸最主要的機制。",c:"16.5"},
 periphchemo:{t:"周邊化學感受器 peripheral chemoreceptors",d:"<b>頸動脈體</b>（頸總動脈分叉，舌咽神經）與<b>主動脈體</b>（主動脈弓，迷走神經）；感測 PO₂↓（&lt; 約 60）、PCO₂↑、H⁺↑。國考考過位置。",m:"「體」偵測化學、「竇」偵測壓力。",c:"16.5"},
 carotidbody:{t:"頸動脈體、主動脈體",d:"<b>頸動脈體</b>：頸總動脈分叉處的小團化學感受細胞（舌咽神經），最重要的周邊化學感受器。<b>主動脈體</b>：主動脈弓附近（迷走神經）。",c:"16.5"},
 heringbreuer:{t:"赫鮑二氏反射 Hering-Breuer reflex",d:"肺過度膨脹時，呼吸道伸張受器經迷走神經抑制吸氣，防止過度膨脹。",c:"16.5"},
 hyperventilation:{t:"過度換氣、換氣不足",d:"<b>過度換氣</b>：換氣超過代謝需要，PCO₂↓ → 呼吸性鹼中毒。<b>換氣不足</b>：PCO₂↑ → 呼吸性酸中毒。",c:"16.5、16.8"},
 oxyhb:{t:"氧合、去氧血紅素",d:"<b>氧合血紅素</b>：結合 O₂，鮮紅。<b>去氧血紅素</b>：放出 O₂，暗紅，較能緩衝 H⁺ 與攜帶 CO₂。",c:"16.6"},
 methb:{t:"變性血紅素 methemoglobin",d:"血基質鐵被氧化成 Fe³⁺，無法結合 O₂；可由某些藥物或過多亞硝酸鹽引起。",c:"16.6"},
 carboxyhb:{t:"碳氧血紅素、一氧化碳中毒",d:"CO 與血紅素的親和力約為 O₂ 的 210 倍，佔據結合位並使剩餘 O₂ 不易釋放；呈鮮紅色，脈搏血氧計可能誤判。治療給高濃度或高壓氧。",c:"16.6"},
 odc:{t:"氧合血紅素解離曲線 oxyhemoglobin dissociation curve",d:"S 形：肺（PO₂ 100）飽和約 97%；靜止組織（40）約 75%；上方平坦提供安全餘裕，下方陡峭利於釋氧。",c:"16.6"},
 bohr:{t:"波爾效應 Bohr effect",d:"H⁺ 增加（pH 下降）與 CO₂ 增加使血紅素對 O₂ 親和力下降、曲線右移，在活動組織釋放更多 O₂。",c:"16.6"},
 bpg:{t:"2,3-BPG（2,3-DPG）",d:"紅血球糖解產生的中間產物，結合去氧血紅素的 β 鏈，降低 O₂ 親和力（右移）；貧血、高海拔時增加，庫存血減少。",c:"16.6"},
 hbf:{t:"胎兒血紅素 HbF",d:"2α＋2γ 鏈，與 2,3-BPG 結合較弱，對 O₂ 親和力較高（左移），能從母體血液取得 O₂；出生後逐漸被 HbA 取代。",c:"16.6；第 20 章"},
 sickle:{t:"鐮刀型貧血 sickle-cell anemia",d:"β 鏈第 6 個胺基酸麩胺酸 → 纈胺酸（HbS），去氧時聚合使紅血球呈鐮刀狀，阻塞微血管並易溶血。",c:"16.6"},
 thalassemia:{t:"地中海型貧血 thalassemia",d:"α 或 β 鏈合成不足造成的小球性貧血；台灣帶因率約 6%，建議婚前或產前篩檢，帶因者不應盲目補鐵。",c:"16.6"},
 carbaminohb:{t:"胺甲醯血紅素 carbaminohemoglobin",d:"CO₂ 與血紅素蛋白質部分的胺基結合的形式，約占 CO₂ 運送的 20%。",c:"16.7"},
 chlorideshift:{t:"氯轉移 chloride shift",d:"組織中紅血球內產生的 HCO₃⁻ 移到血漿，Cl⁻ 移入補位；在肺中反向（逆氯轉移）。",c:"16.7"},
 haldane:{t:"何登效應 Haldane effect",d:"去氧血紅素比氧合血紅素更能攜帶 CO₂ 與 H⁺；組織放出 O₂ 有助於帶走 CO₂，在肺則相反。",c:"16.7"},
 acidbase:{t:"酸鹼平衡 acid-base balance",d:"血液 pH 維持 7.35–7.45；靠緩衝系統、肺（調 CO₂）與腎（調 HCO₃⁻）；HCO₃⁻：CO₂ 約 20：1。",c:"16.8；第 17 章"},
 volatileacid:{t:"揮發性酸、非揮發性酸",d:"<b>揮發性</b>：碳酸，可變成 CO₂ 由肺排出。<b>非揮發性</b>（固定酸）：乳酸、酮體、硫酸、磷酸，由腎排出。",c:"16.8"},
 hh:{t:"韓德森—哈索巴赫方程",d:"pH＝6.1＋log（[HCO₃⁻]／0.03 × PCO₂）；HCO₃⁻ 24、PCO₂ 40 時 pH 為 7.4。",c:"16.8"},
 respacid:{t:"呼吸性酸中毒、鹼中毒",d:"<b>呼吸性酸中毒</b>：換氣不足 → PCO₂↑（COPD、呼吸抑制）。<b>呼吸性鹼中毒</b>：過度換氣 → PCO₂↓（焦慮、高海拔）。腎臟代償。",c:"16.8"},
 metacid:{t:"代謝性酸中毒、鹼中毒",d:"<b>代謝性酸中毒</b>：HCO₃⁻↓（酮酸、乳酸、腹瀉、腎衰竭），過度換氣代償。<b>代謝性鹼中毒</b>：HCO₃⁻↑（嘔吐、制酸劑），換氣減少代償。",c:"16.8"},
 dka:{t:"糖尿病酮酸中毒 diabetic ketoacidosis",d:"胰島素嚴重不足時脂肪大量分解產生酮體，造成代謝性酸中毒、高血糖、脫水；呼吸深快（庫斯毛耳呼吸）、口氣有丙酮味。",c:"16.8；第 19 章"},
 kussmaul:{t:"庫斯毛耳呼吸 Kussmaul breathing",d:"代謝性酸中毒時深而快的呼吸，呼出 CO₂ 以代償。",c:"16.8"},
 hyperpnea:{t:"運動換氣增加 exercise hyperpnea",d:"運動時換氣隨代謝等比例增加，動脈血氣幾乎不變；推測來自大腦前饋與肌肉關節的回饋。",c:"16.9"},
 acclimat:{t:"高海拔適應 acclimatization",d:"PO₂↓ → 換氣↑（呼吸性鹼中毒）→ 腎排 HCO₃⁻；2,3-BPG↑；EPO → 紅血球↑（需鐵）；數天至數週完成。",c:"16.9"},
 ams:{t:"高山症 acute mountain sickness",d:"快速上升到高海拔出現的頭痛、失眠、噁心；嚴重時高海拔肺水腫或腦水腫，最重要處置是下降高度；乙醯唑胺可預防。",c:"16.9"}
});
