Object.assign(GL,{
 sry:{t:"SRY 基因",d:"Y 染色體上的睪丸決定因子，使胚胎約第 7 週的原始性腺發育成睪丸；沒有 SRY 則發育成卵巢。",c:"20.1"},
 sexchrom:{t:"性染色體 sex chromosomes",d:"女性 XX、男性 XY；卵子都帶 X，精子帶 X 或 Y，所以精子決定性別。",c:"20.1"},
 wolffian:{t:"沃爾夫氏管、穆勒氏管",d:"胚胎的兩套管道：<b>沃爾夫氏管</b>受睪固酮作用成副睪、輸精管、儲精囊；<b>穆勒氏管</b>在無 AMH 時成輸卵管、子宮、陰道上部。",c:"20.1"},
 amh:{t:"抗穆勒氏管激素 AMH",d:"胚胎睪丸賽托利氏細胞分泌，使穆勒氏管退化；成年女性由小濾泡顆粒細胞分泌，可估計卵巢庫存量。",c:"20.1、20.4"},
 dht:{t:"二氫睪固酮 DHT",d:"睪固酮經 5α-還原酶轉成的強效雄性素，使外生殖器男性化、前列腺發育；與攝護腺肥大、男性禿頭有關。",c:"20.1、20.3"},
 ais:{t:"雄性素不敏感症候群",d:"染色體 XY、有睪丸也分泌睪固酮，但雄性素受體缺陷，外觀為女性。",c:"20.1"},
 testosterone:{t:"睪固酮 testosterone",d:"雷氏細胞受 LH 刺激分泌：精子生成、男性第二性徵、肌肉骨骼、紅血球生成、性慾；可轉成 DHT 或雌二醇。",c:"20.3；第 11 章"},
 estrogen:{t:"雌激素 estrogens",d:"<b>雌二醇</b>（生育期最主要，濾泡顆粒細胞）、<b>雌酮</b>（停經後最主要，脂肪組織）、<b>雌三醇</b>（懷孕時胎盤）；促進女性第二性徵、子宮內膜增生、骨骼保護。",c:"20.4、20.5"},
 progesterone:{t:"黃體素 progesterone",d:"黃體與胎盤分泌：使子宮內膜進入分泌期、抑制子宮收縮（安胎）、子宮頸黏液變稠、基礎體溫上升、乳腺腺泡發育。",c:"20.4–20.6"},
 inhibin:{t:"抑制素 inhibin",d:"賽托利氏細胞與卵巢顆粒細胞分泌的胜肽激素，選擇性負回饋抑制 FSH。",c:"20.2"},
 hpgaxis:{t:"下視丘—腦垂腺—性腺軸",d:"GnRH（脈衝）→ FSH、LH → 性類固醇與抑制素 → 負回饋；排卵前雌二醇轉為正回饋引起 LH 高峰。",c:"20.2"},
 puberty:{t:"青春期 puberty",d:"GnRH 脈衝增加 → FSH、LH、性類固醇上升 → 第二性徵與生殖能力；受遺傳、kisspeptin、營養與瘦體素影響。",c:"20.2"},
 menarche:{t:"初經 menarche",d:"第一次月經，台灣平均約 12 歲左右；營養改善與肥胖使其提早。",c:"20.2"},
 hypothalamicamenorrhea:{t:"下視丘性無月經",d:"熱量不足、體脂過低、過度運動或壓力使 GnRH 脈衝受抑制而停經；低雌激素導致骨質流失。",c:"20.2"},
 seminiferous:{t:"細精管 seminiferous tubules",d:"睪丸中製造精子的管道，含發育中的生殖細胞與賽托利氏細胞；約占睪丸 90%。",c:"20.3"},
 sertoli:{t:"賽托利氏細胞 Sertoli cells",d:"細精管的支持細胞：形成血睪障壁、提供養分、分泌 ABP、抑制素、AMH；受 FSH 與睪固酮作用。",c:"20.3"},
 leydig:{t:"雷氏細胞 Leydig cells",d:"細精管之間的間質細胞，受 LH 刺激分泌睪固酮。",c:"20.3"},
 btb:{t:"血睪障壁 blood-testis barrier",d:"賽托利氏細胞間的緊密接合，保護減數分裂後的生殖細胞不被免疫系統攻擊。",c:"20.3"},
 spermatogenesis:{t:"精子生成 spermatogenesis",d:"精原細胞 → 初級精母細胞 → 減數分裂 → 精細胞 → 精子（頂體、鞭毛）；約 74 天；一個初級精母細胞產生 4 個精子；需較低溫度。",c:"20.3"},
 acrosome:{t:"頂體、獲能",d:"<b>頂體</b>：精子頭部含酵素的帽狀構造，用來穿過卵子外層。<b>獲能</b>：精子在女性生殖道中獲得受精能力的變化。",c:"20.3、20.6"},
 epididymis:{t:"副睪、輸精管",d:"<b>副睪</b>：精子成熟並獲得運動能力、儲存的地方。<b>輸精管</b>：把精子送往射精管；結紮後不影響睪固酮。",c:"20.3"},
 semen:{t:"精液、儲精囊、前列腺",d:"<b>儲精囊</b>分泌約 60%（果糖、前列腺素）；<b>前列腺</b>約 30%（弱鹼、凝固與液化酵素、PSA）；尿道球腺潤滑。",c:"20.3"},
 erection:{t:"勃起、射精",d:"<b>勃起</b>：副交感 → NO → cGMP → 陰莖血管擴張、海綿體充血（PDE5 抑制劑延長 cGMP）。<b>射精</b>：交感神經使管道平滑肌收縮。",c:"20.3"},
 aromatase:{t:"芳香酶 aromatase",d:"把雄性素轉成雌激素的酵素：卵巢顆粒細胞（受 FSH 誘導）、脂肪組織（停經後雌酮的主要來源）、腦、骨骼、胎盤。",c:"20.3–20.5"},
 oogenesis:{t:"卵子生成 oogenesis",d:"胎兒期形成初級卵母細胞並停在減數分裂前期 I；排卵前完成第一次減數分裂成次級卵母細胞（停在中期 II），受精時才完成；1 個初級卵母細胞 → 1 個卵子。",c:"20.4"},
 oocyte:{t:"初級、次級卵母細胞",d:"<b>初級卵母細胞</b>（2n）：停在前期 I，出生約 100–200 萬個。<b>次級卵母細胞</b>（n）：排卵時的形式，停在中期 II。",c:"20.4"},
 follicle:{t:"濾泡（卵巢）ovarian follicle",d:"卵母細胞與周圍顆粒細胞、鞘膜細胞組成：原始 → 初級（透明帶）→ 次級（濾泡腔）→ 成熟（格拉夫氏）濾泡。（甲狀腺濾泡是不同構造。）",c:"20.4"},
 graafian:{t:"格拉夫氏濾泡 graafian follicle",d:"成熟濾泡：大濾泡腔，卵母細胞位於卵丘、外包放射冠；分泌大量雌二醇，LH 高峰時破裂排卵。",c:"20.4"},
 granulosa:{t:"顆粒細胞、鞘膜細胞（卵巢）",d:"<b>鞘膜細胞</b>受 LH 刺激製造雄性素；<b>顆粒細胞</b>受 FSH 誘導芳香酶把雄性素轉成雌二醇，也分泌抑制素與 AMH。（小腦的顆粒細胞是不同的神經元。）",c:"20.4"},
 zonapellucida:{t:"透明帶、放射冠",d:"<b>透明帶</b>：卵母細胞外的醣蛋白層，受精後變硬防止多精。<b>放射冠</b>：包圍卵子的顆粒細胞層。",c:"20.4、20.6"},
 atresia:{t:"閉鎖 atresia",d:"未成為優勢濾泡的濾泡退化凋亡；女性大多數卵母細胞都在不同階段閉鎖。",c:"20.4"},
 polarbody:{t:"極體 polar body",d:"卵子生成的減數分裂中被排出的小細胞，幾乎不含細胞質；使細胞質集中給卵子。",c:"20.4"},
 ovulation:{t:"排卵 ovulation",d:"LH 高峰後約 24–36 小時成熟濾泡破裂排出次級卵母細胞；卵子約 12–24 小時內可受精。",c:"20.4、20.5"},
 corpusluteum:{t:"黃體、白體",d:"<b>黃體</b>：排卵後濾泡細胞在 LH 作用下形成，分泌黃體素與雌激素；未受精約 10–14 天退化成<b>白體</b>；受精後由 hCG 維持。",c:"20.4"},
 endometrium:{t:"子宮內膜 endometrium",d:"子宮內層：功能層隨月經週期增生、分泌、剝落；基底層負責再生；胚囊在此著床。",c:"20.4、20.5"},
 oviduct:{t:"輸卵管 uterine tube",d:"繖部捕捉卵子、壺腹部是通常受精處，以纖毛與蠕動把受精卵送往子宮；在此著床稱子宮外孕。",c:"20.4"},
 menscycle:{t:"月經週期 menstrual cycle",d:"約 28 天：月經期（第 1–5 天）→ 增生期（雌二醇）→ 排卵（LH 高峰，約第 14 天）→ 分泌期（黃體素）→ 黃體退化 → 月經。",c:"20.5"},
 follicularphase:{t:"濾泡期、黃體期",d:"<b>濾泡期</b>：FSH 使濾泡發育、雌二醇上升，長度較不固定。<b>黃體期</b>：黃體分泌黃體素與雌激素，約 14 天較固定。",c:"20.5"},
 lhsurge:{t:"LH 高峰 LH surge",d:"排卵前雌二醇持續高濃度轉為正回饋，使 LH（與 FSH）大量釋放，觸發排卵與黃體形成。",c:"20.5"},
 bbt:{t:"基礎體溫 basal body temperature",d:"清晨未活動時的體溫；黃體素使排卵後上升約 0.3–0.5℃，可推測是否排卵。",c:"20.5"},
 ocp:{t:"口服避孕藥 oral contraceptives",d:"合成雌激素＋黃體素持續負回饋，抑制 FSH 與 LH 高峰 → 不排卵；並使子宮頸黏液變稠；停藥時撤退性出血。",c:"20.5"},
 menopause:{t:"停經、更年期 menopause",d:"連續 12 個月無月經（平均約 50 歲）；濾泡耗盡 → 雌二醇與抑制素↓ → FSH、LH↑↑；熱潮紅、骨質流失、心血管風險↑。",c:"20.5（國考）"},
 estrone:{t:"雌酮 estrone",d:"停經後最主要的雌激素，由脂肪組織的芳香酶把腎上腺（與卵巢間質）分泌的雄烯二酮轉成。國考考過。",c:"20.5"},
 androstenedione:{t:"雄烯二酮 androstenedione",d:"腎上腺皮質與卵巢鞘膜細胞分泌的弱雄性素，可經芳香酶轉成雌酮，是停經後雌激素的原料。",c:"20.4、20.5"},
 fertilization:{t:"受精 fertilization",d:"通常在輸卵管壺腹部：獲能精子經頂體反應穿過放射冠與透明帶，膜融合後皮質反應防多精，卵子完成第二次減數分裂，形成受精卵。",c:"20.6"},
 blastocyst:{t:"桑椹胚、胚囊",d:"受精卵卵裂成<b>桑椹胚</b>（約第 3–4 天進入子宮），再成<b>胚囊</b>：外層滋養層、內細胞團（將成胚胎）。",c:"20.6"},
 implantation:{t:"著床 implantation",d:"胚囊約受精後第 6–7 天埋入分泌期的子宮內膜，滋養層開始分泌 hCG。",c:"20.6"},
 trophoblast:{t:"滋養層 trophoblast",d:"胚囊外層細胞，侵入子宮內膜、分泌 hCG，日後形成胎盤的胎兒部分（絨毛膜）。",c:"20.6"},
 placenta:{t:"胎盤 placenta",d:"胎兒絨毛膜與母體基蛻膜組成；母血與胎血不直接混合，交換 O₂、養分、廢物與 IgG；分泌 hCG、黃體素、雌三醇、hPL。",c:"20.6"},
 fetoplacental:{t:"胎兒—胎盤單位 fetoplacental unit",d:"胎盤缺乏部分酵素，需利用胎兒腎上腺分泌的 DHEA-S 為原料製造雌激素（主要是雌三醇）。",c:"20.6"},
 gdm:{t:"妊娠糖尿病 gestational diabetes",d:"懷孕中後期 hPL 等造成胰島素阻抗，β 細胞代償不足而高血糖；台灣建議 24–28 週做 OGTT 篩檢；日後第 2 型糖尿病風險較高。",c:"20.6"},
 ntd:{t:"神經管缺陷 neural tube defects",d:"神經管在受孕後約 3–4 週未正常閉合（無腦症、脊柱裂）；孕前至少 1 個月開始每天補充 400 µg 葉酸可大幅降低風險。",c:"20.6"},
 parturition:{t:"分娩 parturition",d:"胎頭撐開子宮頸 → 催產素 → 子宮收縮（與前列腺素）→ 更多催產素的正回饋；分子宮頸擴張、胎兒娩出、胎盤娩出三期。",c:"20.6"},
 lactation:{t:"泌乳 lactation",d:"產後雌激素與黃體素下降，泌乳素開始製造乳汁；吸吮使泌乳素（製造）與催產素（噴乳）分泌。",c:"20.6"},
 milkejection:{t:"噴乳反射 milk-ejection reflex",d:"吸吮 → 下視丘 → 腦垂腺後葉催產素 → 乳腺腺泡周圍肌上皮細胞收縮擠出乳汁；可被條件化，也被壓力抑制。",c:"20.6"}
});
