/* ---- ch13 ---- */
Object.assign(GL,{"plasma2":{"t":"血漿、血清 plasma / serum","d":"<b>血漿</b>：血液加抗凝劑離心後的液體部分，含凝血因子。<b>血清</b>：血液凝固後擠出的液體，凝血因子已用掉。","c":"13.2"},
"hct":{"t":"血比容 hematocrit","d":"紅血球占全血體積的百分比，約 45%（男性略高）；貧血時降低、脫水或高海拔時升高。","c":"13.2"},
"albumin":{"t":"白蛋白 albumin","d":"肝臟製造、量最多的血漿蛋白，產生膠體滲透壓把水留在血管內，也運送脂肪酸、膽紅素、藥物。過低 → 水腫。","c":"13.2；第 14 章"},
"globulin":{"t":"球蛋白 globulins","d":"<b>α、β 球蛋白</b>（肝臟）：運送脂質、脂溶性維生素、鐵等。<b>γ 球蛋白</b>：抗體。","c":"13.2；第 15 章"},
"fibrinogen":{"t":"纖維蛋白原 fibrinogen","d":"肝臟製造的可溶性血漿蛋白，凝血時被凝血酶切成纖維蛋白。","c":"13.2"},
"rbc":{"t":"紅血球 erythrocyte","d":"雙凹圓盤、無核無粒線體（靠糖解）、約 500 萬/mm³、壽命約 120 天，內含血紅素運送 O₂。","c":"13.2"},
"hemoglobin":{"t":"血紅素 hemoglobin","d":"紅血球內的含鐵蛋白：四條球蛋白鏈各帶一個血基質，每個血基質的 Fe²⁺ 結合一個 O₂。","c":"13.2；第 16 章"},
"anemia":{"t":"貧血 anemia","d":"血紅素或紅血球數異常低：缺鐵（小球性、低色素）、葉酸或 B12 缺乏（巨球性）、腎病（EPO 不足）、溶血、失血等。","c":"13.2"},
"wbc":{"t":"白血球 leukocyte","d":"有核的血球，能穿出微血管到組織防禦。顆粒球：嗜中性、嗜酸性、嗜鹼性；無顆粒球：淋巴球、單核球。","c":"13.2；第 15 章"},
"neutrophil":{"t":"嗜中性球 neutrophil","d":"最多的白血球（50–70%），多葉核，最先到感染處吞噬細菌；膿主要是死掉的嗜中性球。","c":"13.2；第 15 章"},
"eosinophil":{"t":"嗜酸性球、嗜鹼性球","d":"<b>嗜酸性球</b>：對抗寄生蟲、參與過敏。<b>嗜鹼性球</b>：最少，釋放組織胺與肝素。","c":"13.2；第 15 章"},
"lymphocyte":{"t":"淋巴球 lymphocyte","d":"第二多的白血球，大圓核；B 細胞（產生抗體）與 T 細胞（細胞免疫），負責專一性免疫。","c":"13.2；第 15 章"},
"monocyte":{"t":"單核球 monocyte","d":"最大的白血球，進入組織後變成巨噬細胞。","c":"13.2；第 15 章"},
"macrophage":{"t":"巨噬細胞 macrophage","d":"由單核球變成的大型吞噬細胞，吞噬病原、老舊紅血球與氧化 LDL，並呈現抗原；在脾臟分解紅血球。","c":"13.2、13.7；第 15 章"},
"platelet":{"t":"血小板 platelet","d":"骨髓巨核細胞的細胞質碎片，無核、壽命 5–9 天；聚集成血小板栓並釋放促凝物質。","c":"13.2"},
"megakaryocyte":{"t":"巨核細胞 megakaryocyte","d":"骨髓中巨大的細胞，細胞質剝落成血小板；受血小板生成素刺激。","c":"13.2"},
"hematopoiesis":{"t":"造血作用 hematopoiesis","d":"製造血球的過程；出生後主要在紅骨髓，所有血球來自多能造血幹細胞。","c":"13.2"},
"erythropoiesis":{"t":"紅血球生成 erythropoiesis","d":"受腎臟的 EPO 調控（缺氧時增加）；需要鐵、葉酸、維生素 B12、蛋白質等。","c":"13.2"},
"csf":{"t":"群落刺激因子 colony-stimulating factors","d":"刺激骨髓中白血球前驅細胞增生分化的細胞激素；可用於化療後提升白血球。","c":"13.2"},
"heme":{"t":"血基質 heme","d":"血紅素中含鐵的環狀分子（紫質環＋Fe²⁺）；分解時鐵被回收，環變成膽綠素再變膽紅素。","c":"13.2"},
"bilirubin":{"t":"膽紅素 bilirubin","d":"血基質在脾臟等處巨噬細胞內分解的產物（經膽綠素）；與白蛋白結合到肝臟，結合葡萄糖醛酸後隨膽汁排出。累積 → 黃疸。","c":"13.2；第 18 章"},
"biliverdin":{"t":"膽綠素 biliverdin","d":"血基質環被打開後的綠色色素，再還原成膽紅素（瘀青由紫變綠變黃就是這個變化）。","c":"13.2"},
"jaundice":{"t":"黃疸 jaundice","d":"血中膽紅素過高，使皮膚與眼白變黃；原因有溶血過多、肝臟處理不良、膽道阻塞。新生兒常見生理性黃疸。","c":"13.2；第 18 章"},
"transferrin":{"t":"運鐵蛋白、鐵蛋白 transferrin / ferritin","d":"<b>運鐵蛋白</b>：血漿中運送鐵的蛋白（到骨髓）。<b>鐵蛋白</b>：在肝、脾、骨髓儲存鐵；血清鐵蛋白反映鐵儲存量。","c":"13.2"},
"hepcidin":{"t":"鐵調素 hepcidin","d":"肝臟分泌的鐵調節激素：鐵多或發炎時增加 → 減少腸道吸收鐵、巨噬細胞留住鐵（慢性病貧血的原因之一）。","c":"13.2；第 18 章"},
"intrinsic":{"t":"內在因子 intrinsic factor","d":"胃的壁細胞分泌的一種醣蛋白，專門用來「接住」維生素 B12，讓 B12 能在小腸最末端（迴腸）被吸收。沒有它，吃再多 B12 也吸收不到。","w":"胃的<b>壁細胞</b>——和分泌鹽酸的是同一種細胞。","f":"B12 從食物蛋白釋出後，先由 R 蛋白保護通過胃；到了十二指腸，胰蛋白酶分解 R 蛋白，B12 改和內在因子結合 → 一起走到迴腸末端 → 由專門辨認「B12–內在因子」的受體吸收進入血液。","e":"胃切除、萎縮性胃炎（老年人常見）、自體免疫破壞壁細胞 → 內在因子不足 → B12 吸收不良 → <b>惡性貧血</b>（巨球性貧血＋神經症狀）；這時口服一般劑量沒有用，常用注射補充 B12。","n":"早期研究惡性貧血時，發現要治好必須有食物裡的「外在因子」（就是 B12）加上胃液裡身體自己製造的「內在因子」，名稱因此而來。","m":"壁細胞做兩件事：<b>鹽酸＋內在因子</b>。","c":"13.2；第 18 章；營養生化學 9-68"},
"abo":{"t":"ABO 血型","d":"由紅血球表面 A、B 抗原決定；血漿中天生有對抗自己沒有的抗原的抗體。輸錯 → 凝集與溶血。","c":"13.2"},
"rh":{"t":"Rh 血型、新生兒溶血症","d":"有 D 抗原＝Rh⁺。Rh⁻ 者接觸 Rh⁺ 血後才產生抗 D；Rh⁻ 母親第二胎 Rh⁺ 胎兒可能被抗體破壞紅血球（新生兒溶血症），可用 RhoGAM 預防。","c":"13.2"},
"agglutination":{"t":"凝集 agglutination","d":"抗體同時結合多個紅血球上的抗原，使紅血球黏成團塊；是血型鑑定與輸血反應的基礎。","c":"13.2"},
"hemostasis":{"t":"止血 hemostasis","d":"三步：血管收縮 → 血小板栓 → 凝血（纖維蛋白網）。","c":"13.2"},
"coag":{"t":"凝血、凝血因子 coagulation / clotting factors","d":"一連串多由肝臟製造的蛋白酶原依序活化，最後產生纖維蛋白；內在路徑（XII）與外在路徑（組織因子 III、VII）會合於因子 X。","c":"13.2"},
"thrombin":{"t":"凝血酶原、凝血酶 prothrombin / thrombin","d":"<b>凝血酶原</b>（因子 II，需維生素 K）被活化成<b>凝血酶</b>，凝血酶把纖維蛋白原切成纖維蛋白。","c":"13.2"},
"fibrin":{"t":"纖維蛋白 fibrin","d":"纖維蛋白原被凝血酶切割後聚合成的不溶性網狀蛋白，網住血球形成血塊。","c":"13.2"},
"tissuefactor":{"t":"組織因子 tissue factor","d":"受損組織釋放的因子 III，啟動外在凝血路徑。","c":"13.2"},
"vwf":{"t":"馮威里氏因子 von Willebrand factor","d":"讓血小板黏附到露出的膠原蛋白上的血漿蛋白；缺乏時容易出血。","c":"13.2"},
"vitk":{"t":"維生素 K vitamin K（葉綠醌、甲萘醌）","d":"讓<b>凝血因子</b>和<b>骨骼蛋白</b>能抓住鈣而發揮作用的脂溶性維生素；腸道細菌也會製造一部分。","c":"13.2；第 18 章；營養生化學 10-49～10-58","tag":"營養素","nu":"<b>來源</b>：K₁（葉綠醌）——深綠色葉菜（菠菜、地瓜葉、青花菜）、植物油；K₂（甲萘醌類）——腸道細菌、納豆、發酵乳酪、肝臟。<br><b>建議量</b>（國人 DRIs 第八版，足夠攝取量）：成人男 120、女 90 μg；懷孕、哺乳不增加；未訂上限攝取量。","ch":"共同結構是 2-甲基-1,4-萘醌環，接上不同長度的側鏈：K₁ 側鏈一種、K₂ 側鏈長短不一（MK-4、MK-7 等）。","bc":"<b>γ-麩胺醯羧化酶</b>的輔助因子：把蛋白質上特定的麩胺酸（Glu）加上一個羧基，變成 <b>γ-羧基麩胺酸（Gla）</b>，Gla 的兩個負電荷能夾住 Ca²⁺，蛋白質才能附著到血小板磷脂膜或骨骼上。<br>需要 K 的蛋白質：凝血因子 <b>II（凝血酶原）、VII、IX、X</b>，抗凝血的蛋白 C、蛋白 S，骨骼的<b>骨鈣素</b>。<br>用過的維生素 K 變成環氧化物，由<b>維生素 K 環氧化物還原酶（VKOR）</b>回收再用。","mb":"VKOR 的基因（VKORC1）多型性使不同的人對 warfarin 劑量需求差很多，是藥物基因體學的經典例子。","ph":"肝臟製造凝血因子，凝血連鎖反應需要 Ca²⁺（第 13 章）；骨骼礦化（第 19 章）；脂溶性，吸收需要膽鹽（第 18 章）。","dt":"<b>服用 warfarin（抗凝血藥）</b>：warfarin 抑制 VKOR；維生素 K 攝取忽多忽少會讓藥效不穩，所以要<b>保持每天攝取量穩定</b>，不是完全不吃綠色蔬菜。<br><b>新生兒</b>：胎盤傳送少、母乳含量低、腸道還沒有細菌 → 出生時常規注射維生素 K，預防新生兒出血症。<br><b>長期使用廣效抗生素</b>、<b>脂肪吸收不良</b>、<b>肝病</b>：容易不足或凝血因子做不出來。","m":"<b>K 讓凝血因子長出「夾鈣的鉗子」（Gla）</b>；需要 K 的凝血因子：<b>2、7、9、10</b>（記「1972」去掉 1）。","ex":"warfarin 是<b>維生素 K 拮抗劑</b>，作用在 VKOR；病人的飲食重點是<b>維生素 K 攝取量穩定</b>。新生兒出生後<b>注射維生素 K</b>。"},
"plasmin":{"t":"胞漿素 plasmin","d":"由胞漿素原被 t-PA 等活化而成，分解纖維蛋白、溶解血塊（纖維蛋白溶解）。","c":"13.2"},
"tpa":{"t":"組織胞漿素原活化劑 t-PA","d":"把胞漿素原活化成胞漿素的酵素，可作為急性缺血性中風或心肌梗塞的溶栓藥。","c":"13.2"},
"heparin":{"t":"肝素 heparin","d":"活化抗凝血酶 III 而抑制凝血酶等的抗凝劑，需注射；嗜鹼性球與肥大細胞也會釋放。","c":"13.2"},
"coumarin":{"t":"香豆素類 coumarins（warfarin）","d":"口服抗凝劑，抑制維生素 K 的再生（還原），使依賴維生素 K 的凝血因子 II、VII、IX、X 無法活化。服藥者維生素 K 攝取應穩定。","c":"13.2"},
"hemophilia":{"t":"血友病 hemophilia","d":"X 性聯遺傳的凝血因子缺乏：A 型缺因子 VIII、B 型缺因子 IX；容易出血不止。","c":"13.2"},
"atrium":{"t":"心房、心室 atria / ventricles","d":"<b>心房</b>：上方兩腔，收集回流的血。<b>心室</b>：下方兩腔，把血打出去；左心室壁最厚。","c":"13.3"},
"pulmcirc":{"t":"肺循環、體循環","d":"<b>肺循環</b>：右心室 → 肺動脈（去氧血）→ 肺 → 肺靜脈（充氧血）→ 左心房。<b>體循環</b>：左心室 → 主動脈 → 全身 → 腔靜脈 → 右心房。","c":"13.3"},
"aorta":{"t":"主動脈 aorta","d":"從左心室發出、最大的彈性動脈，把充氧血送往全身。","c":"13.3"},
"venacava":{"t":"腔靜脈 venae cavae","d":"上腔靜脈與下腔靜脈，把全身的去氧血送回右心房。","c":"13.3"},
"pulmart":{"t":"肺動脈、肺靜脈","d":"<b>肺動脈</b>：右心室到肺，裝的是<b>去氧血</b>。<b>肺靜脈</b>：肺到左心房，裝的是<b>充氧血</b>。依血流方向命名。","c":"13.3"},
"avvalve":{"t":"房室瓣 atrioventricular valves","d":"心房與心室之間的瓣膜：右三尖瓣、左二尖瓣（僧帽瓣）；以腱索連到乳頭肌，防止心室收縮時倒流回心房。","c":"13.3"},
"mitral":{"t":"三尖瓣、二尖瓣（僧帽瓣）","d":"<b>三尖瓣</b>：右心房與右心室之間。<b>二尖瓣</b>：左心房與左心室之間，形狀像主教的帽子（mitre），所以叫僧帽瓣。","c":"13.3"},
"slvalve":{"t":"半月瓣 semilunar valves","d":"心室與動脈之間的瓣膜：肺動脈瓣、主動脈瓣；防止心室放鬆時血液從動脈倒流。","n":"三片半月形瓣葉。","c":"13.3"},
"chordae":{"t":"腱索、乳頭肌","d":"<b>腱索</b>：連接房室瓣與心室壁<b>乳頭肌</b>的細繩狀結締組織；乳頭肌收縮拉住瓣膜，防止它翻向心房。","c":"13.3"},
"heartsound":{"t":"心音 heart sounds","d":"<b>第一心音「隆」</b>：房室瓣關閉（心縮期開始）。<b>第二心音「咚」</b>：半月瓣關閉（心舒期開始）。","c":"13.3–13.5"},
"murmur":{"t":"心雜音 heart murmur","d":"異常血流造成的聲音：瓣膜狹窄、瓣膜閉鎖不全（逆流）、中膈缺損。","c":"13.3"},
"stenosis":{"t":"僧帽瓣狹窄、脫垂","d":"<b>狹窄</b>：瓣膜鈣化變硬（常因風濕熱），阻礙左心房到左心室的血流，可造成肺高血壓。<b>脫垂</b>：瓣膜翻向心房造成逆流。","c":"13.3"},
"septaldefect":{"t":"中膈缺損 septal defect","d":"心房或心室中膈有洞，血液在左右之間分流；胎兒的卵圓孔未關閉也屬此類。","c":"13.3"},
"cardcycle":{"t":"心動週期 cardiac cycle","d":"心臟一次收縮與放鬆的過程；心率 75 時約 0.8 秒，心縮期約 0.3 秒、心舒期約 0.5 秒。","c":"13.4"},
"systole":{"t":"心縮期、心舒期 systole / diastole","d":"<b>心縮期</b>：心肌收縮；<b>心舒期</b>：心肌放鬆。通常指心室。心跳加快主要縮短心舒期。","c":"13.4"},
"edv":{"t":"心舒期末容積、心縮期末容積 EDV / ESV","d":"<b>EDV</b>：心舒期結束時心室的血量（約 130 mL）。<b>ESV</b>：心縮期結束後心室剩下的血量（約 60 mL）。","c":"13.4；第 14 章"},
"sv":{"t":"心搏量 stroke volume","d":"每次心跳一個心室打出的血量＝EDV－ESV，約 70 mL。","c":"13.4；第 14 章"},
"ef":{"t":"射出分率 ejection fraction","d":"心搏量 ÷ EDV，正常約 55–70%；心衰竭時降低。","c":"13.4；第 14 章"},
"isovol":{"t":"等容積收縮、等容積放鬆","d":"四個瓣膜都關閉、心室容積不變的兩段時期：<b>等容積收縮</b>（壓力上升，在 AV 瓣關後、半月瓣開前）；<b>等容積放鬆</b>（壓力下降，在半月瓣關後、AV 瓣開前）。","c":"13.4"},
"dicrotic":{"t":"重搏切跡 dicrotic notch","d":"主動脈壓曲線上的小凹陷，出現在半月瓣關閉時（血液短暫倒衝、瓣膜回彈）。","c":"13.4"},
"automaticity":{"t":"自動性 automaticity","d":"心臟自己產生節律的能力，不需神經刺激；神經只調整快慢。","c":"13.5"},
"sanode":{"t":"竇房結 sinoatrial node","d":"位於右心房壁上的特化心肌，是正常的節律點，產生竇性心律。","n":"位在上腔靜脈開口的「竇」附近。","c":"13.5"},
"avnode":{"t":"房室結 atrioventricular node","d":"右心房底部、房室之間唯一的電訊號通道；傳導很慢，造成延遲讓心房先收縮。","c":"13.5"},
"ectopic":{"t":"異位節律點 ectopic pacemaker","d":"竇房結以外能自發產生節律的部位（房室結約 40–60、浦金耶氏纖維約 20–40 次/分），竇房結失效時接手。","c":"13.5"},
"pacemaker":{"t":"節律點電位 pacemaker potential","d":"竇房結細胞在兩次心跳之間的自發緩慢去極化（心舒期去極化），由 HCN 通道 Na⁺ 流入造成，到閾值即引發動作電位。","c":"13.5"},
"hcn":{"t":"HCN 通道","d":"過極化活化、環核苷酸閘控通道：再極化到最低時打開讓 Na⁺ 流入；cAMP 使它更容易打開（交感加快心率）。","c":"13.5"},
"plateau":{"t":"平台期 plateau phase","d":"心肌動作電位中維持約 −15 mV 達 200–300 毫秒的時期，由 Ca²⁺ 流入與 K⁺ 流出平衡造成；使不反應期很長。","c":"13.5"},
"his":{"t":"希氏束、束支","d":"房室結之後的傳導纖維（房室束），在心室中膈分成左、右束支，再延伸成浦金耶氏纖維。","c":"13.5"},
"purkinje":{"t":"浦金耶氏纖維 Purkinje fibers","d":"遍布心室壁的傳導纖維，傳導最快（約 5 m/s），使心室從心尖往上幾乎同時收縮。","c":"13.5"},
"ecg":{"t":"心電圖 electrocardiogram（ECG / EKG）","d":"記錄心臟電性活動傳到皮膚的電壓變化：P 波（心房去極化）、QRS（心室去極化）、T 波（心室再極化）。","c":"13.5"},
"pwave":{"t":"P 波、QRS 波、T 波","d":"<b>P</b>：心房去極化。<b>QRS</b>：心室去極化（心房再極化被蓋住）。<b>T</b>：心室再極化。","c":"13.5"},
"printerval":{"t":"P-R（P-Q）間期、S-T 節段","d":"<b>P-R 間期</b>：心房開始去極化到心室開始去極化，反映房室傳導時間。<b>S-T 節段</b>：心室平台期；心肌缺血時上升或下降。","c":"13.5、13.7"},
"lead":{"t":"心電圖導程 ECG leads","d":"標準 12 導程：雙極肢導 I、II、III，加強單極肢導 aVR、aVL、aVF，胸導 V1–V6。","c":"13.5"},
"tunica":{"t":"內膜、中膜、外膜","d":"血管壁三層：<b>內膜</b>（內皮＋基底膜）、<b>中膜</b>（平滑肌，動脈較厚）、<b>外膜</b>（結締組織）。","c":"13.6"},
"elasticart":{"t":"彈性動脈、肌肉性動脈","d":"<b>彈性動脈</b>（近心臟）：射血時擴張、心舒時回彈，使血流連續。<b>肌肉性動脈</b>（較遠）：平滑肌比例高、阻力較大。","c":"13.6"},
"arteriole":{"t":"小動脈 arteriole","d":"直徑約 20–30 µm、阻力最大的血管；平滑肌舒縮控制流入微血管的血量與血壓。","c":"13.6；第 14 章"},
"capillary":{"t":"微血管 capillary","d":"最小的血管（7–10 µm），只有一層內皮，是血液與組織交換物質的地方。","c":"13.6；第 14 章"},
"precap":{"t":"微血管前括約肌 precapillary sphincter","d":"微血管入口的平滑肌環，收縮或放鬆控制該微血管的血流。","c":"13.6"},
"captype":{"t":"微血管的三種類型","d":"<b>連續型</b>：肌肉、脂肪、中樞神經（血腦障壁）。<b>窗孔型</b>：腎臟、小腸、內分泌腺。<b>不連續型（竇狀）</b>：肝、骨髓、脾，蛋白質可通過。","c":"13.6"},
"vein":{"t":"靜脈 vein","d":"壓力低（約 2 mmHg）、壁薄腔大、容納約 2/3 血液（容量血管）；有靜脈瓣。","c":"13.6；第 14 章"},
"musclepump":{"t":"骨骼肌幫浦、呼吸幫浦","d":"<b>骨骼肌幫浦</b>：肌肉收縮擠壓靜脈把血往心臟推。<b>呼吸幫浦</b>：吸氣時胸腔壓降低、腹壓增加，幫助靜脈回流。","c":"13.6"},
"venvalve":{"t":"靜脈瓣 venous valves","d":"靜脈內膜形成的口袋狀瓣膜，讓血液只能往心臟方向流；失能時造成靜脈曲張。","c":"13.6"},
"varicose":{"t":"靜脈曲張 varicose veins","d":"靜脈長期被撐大、瓣膜關不緊，血液積聚使淺層靜脈彎曲膨出；久站、懷孕、肥胖為危險因子。","c":"13.6"},
"atherosclerosis":{"t":"動脈粥狀硬化 atherosclerosis","d":"最常見的動脈硬化：內皮損傷 → 氧化 LDL 被巨噬細胞吞成泡沫細胞 → 平滑肌移入 → 纖維帽 → 斑塊；是一種慢性發炎性疾病。","n":"athero＝粥，sclerosis＝變硬。","c":"13.7"},
"arteriosclerosis":{"t":"動脈硬化 arteriosclerosis","d":"動脈壁變硬、失去彈性的總稱，動脈粥狀硬化是最常見的型態。","c":"13.7"},
"plaque":{"t":"斑塊 plaque","d":"動脈內膜中由脂質、泡沫細胞、平滑肌與纖維帽組成的病灶，凸入管腔；纖維帽破裂易形成血栓。","c":"13.7"},
"foamcell":{"t":"泡沫細胞、脂肪條紋","d":"<b>泡沫細胞</b>：吞下大量氧化 LDL 的巨噬細胞，看起來充滿泡泡。聚集成<b>脂肪條紋</b>，是動脈粥狀硬化的早期病灶。","c":"13.7"},
"ldl":{"t":"低密度脂蛋白 LDL","d":"把膽固醇從肝臟運往組織的脂蛋白；濃度高與動脈粥狀硬化有關（「壞膽固醇」）；細胞經 LDL 受體攝取。","c":"13.7；第 19 章"},
"hdl":{"t":"高密度脂蛋白 HDL","d":"把膽固醇從周邊組織與斑塊帶回肝臟（反向膽固醇運輸）的脂蛋白，「好膽固醇」；運動可提高。","c":"13.7；第 19 章"},
"statin":{"t":"斯達汀類 statins","d":"抑制 HMG-CoA 還原酶（膽固醇合成的限速酵素）的降血脂藥，使肝細胞增加 LDL 受體、降低血中 LDL。","c":"13.7"},
"crp":{"t":"C 反應蛋白 C-reactive protein（CRP）","d":"肝臟在發炎時製造的急性期蛋白；高敏感度 CRP 可作為心血管風險指標。","c":"13.7；第 15 章"},
"ischemia":{"t":"缺血 ischemia","d":"組織血流不足以供應所需的氧，細胞改行無氧代謝；持續過久會壞死（梗塞）。","c":"13.7"},
"angina":{"t":"心絞痛 angina pectoris","d":"冠狀動脈狹窄使心肌缺血引起的胸痛，常在運動或激動時出現；硝化甘油（產生 NO）可緩解。","c":"13.7"},
"mi":{"t":"心肌梗塞 myocardial infarction","d":"冠狀動脈完全阻塞使心肌壞死（心臟病發作）；心電圖 S-T 改變，血中心肌肌鈣蛋白、CK-MB 升高。","c":"13.7"},
"arrhythmia":{"t":"心律不整 arrhythmia","d":"心跳的速率或節律異常，可由心電圖判讀：心搏過速、過緩、纖維顫動、房室傳導阻滯等。","c":"13.7"},
"tachy":{"t":"心搏過速、心搏過緩","d":"<b>過速</b>：靜止心率 &gt; 100 次/分。<b>過緩</b>：&lt; 60 次/分（耐力運動員可正常偏低）。","c":"13.7"},
"afib":{"t":"心房纖維顫動 atrial fibrillation","d":"心房不規則亂顫、沒有正常 P 波、心室跳動不規則；心房血流淤滯易形成血栓 → 中風。","c":"13.7"},
"vfib":{"t":"心室纖維顫動 ventricular fibrillation","d":"心室只是亂顫、無法打血，數分鐘內死亡；需立即 CPR 與電擊去顫（AED）。","c":"13.7"},
"avblock":{"t":"房室傳導阻滯 AV node block","d":"一度：P-R 間期延長。二度：部分 P 波後沒有 QRS。三度：完全阻滯，心房心室各跳各的，常需心律調節器。","c":"13.7"},
"lymph":{"t":"淋巴 lymph","d":"進入微淋巴管的組織液（含少量蛋白質、淋巴球；腸道來的含乳糜微粒）。","c":"13.8"},
"lymphcap":{"t":"微淋巴管 lymphatic capillaries","d":"末端封閉、內皮邊緣重疊成單向小瓣的細管，收集組織間多餘的液體與蛋白質。","c":"13.8"},
"lacteal":{"t":"乳糜管 lacteal","d":"小腸絨毛中的微淋巴管，吸收乳糜微粒（脂肪與脂溶性維生素），不經肝門靜脈。","c":"13.8；第 18 章"},
"thoracicduct":{"t":"胸管 thoracic duct","d":"最大的淋巴管，收集下半身與左上半身的淋巴，注入左鎖骨下靜脈；起點膨大處為乳糜池。","c":"13.8"},
"lymphnode":{"t":"淋巴結 lymph nodes","d":"沿淋巴管分布的豆形器官，內含巨噬細胞與淋巴球，過濾淋巴並產生免疫反應。","c":"13.8；第 15 章"},
"spleen":{"t":"脾臟 spleen","d":"左上腹的淋巴器官：過濾血液、由巨噬細胞破壞老舊紅血球（血基質→膽紅素）、儲存血小板、產生免疫反應。","c":"13.2、13.8；第 15 章"},
"lymphedema":{"t":"淋巴水腫 lymphedema","d":"淋巴回流受阻（淋巴結切除、絲蟲病）使組織液與蛋白質累積造成的腫脹。","c":"13.8"},
"edema":{"t":"水腫 edema","d":"組織間液過多造成的腫脹；原因：微血管壓力高、血漿白蛋白低、微血管通透性增加、淋巴阻塞。","c":"13.2、13.8；第 14 章"},
"chylomicron":{"t":"乳糜微粒 chylomicron","d":"小腸細胞把吸收的三酸甘油酯、膽固醇、脂溶性維生素包裝成的最大脂蛋白，經乳糜管與淋巴進入血液。","c":"13.8；第 18 章"},
"mct":{"t":"中鏈脂肪酸 MCT","d":"8–12 碳的脂肪酸，不需組成乳糜微粒，可直接經肝門靜脈吸收；用於脂肪吸收不良或淋巴異常的飲食治療。","c":"13.8；第 18 章"}});
Object.assign(GL_ALIAS,{"血清":"plasma2","血比容":"hct","白蛋白":"albumin","球蛋白":"globulin","γ 球蛋白":"globulin","纖維蛋白原":"fibrinogen","紅血球":"rbc","血紅素":"hemoglobin","貧血":"anemia","白血球":"wbc","嗜中性球":"neutrophil","嗜酸性球":"eosinophil","嗜鹼性球":"eosinophil","淋巴球":"lymphocyte","單核球":"monocyte","巨噬細胞":"macrophage","血小板":"platelet","巨核細胞":"megakaryocyte","造血作用":"hematopoiesis","紅血球生成":"erythropoiesis","群落刺激因子":"csf","血基質":"heme","膽紅素":"bilirubin","膽綠素":"biliverdin","黃疸":"jaundice","運鐵蛋白":"transferrin","鐵蛋白":"transferrin","鐵調素":"hepcidin","內在因子":"intrinsic","ABO 血型":"abo","Rh 血型":"rh","新生兒溶血症":"rh","凝集":"agglutination","止血":"hemostasis","凝血因子":"coag","凝血酶原":"thrombin","凝血酶":"thrombin","纖維蛋白":"fibrin","組織因子":"tissuefactor","馮威里氏因子":"vwf","胞漿素":"plasmin","胞漿素原":"plasmin","t-PA":"tpa","肝素":"heparin","香豆素":"coumarin","warfarin":"coumarin","血友病":"hemophilia","心房":"atrium","心室":"atrium","肺循環":"pulmcirc","體循環":"pulmcirc","主動脈":"aorta","腔靜脈":"venacava","肺動脈":"pulmart","肺靜脈":"pulmart","房室瓣":"avvalve","三尖瓣":"mitral","二尖瓣":"mitral","僧帽瓣":"mitral","半月瓣":"slvalve","腱索":"chordae","乳頭肌":"chordae","第一心音":"heartsound","第二心音":"heartsound","心雜音":"murmur","僧帽瓣狹窄":"stenosis","僧帽瓣脫垂":"stenosis","中膈缺損":"septaldefect","心動週期":"cardcycle","心縮期":"systole","心舒期":"systole","心舒期末容積":"edv","心縮期末容積":"edv","EDV":"edv","ESV":"edv","心搏量":"sv","射出分率":"ef","等容積收縮":"isovol","等容積放鬆":"isovol","重搏切跡":"dicrotic","自動性":"automaticity","竇房結":"sanode","房室結":"avnode","異位節律點":"ectopic","節律點電位":"pacemaker","HCN 通道":"hcn","平台期":"plateau","希氏束":"his","束支":"his","浦金耶氏纖維":"purkinje","心電圖":"ecg","P 波":"pwave","QRS":"pwave","T 波":"pwave","P-R":"printerval","S-T 節段":"printerval","導程":"lead","彈性動脈":"elasticart","肌肉性動脈":"elasticart","小動脈":"arteriole","微血管":"capillary","微血管前括約肌":"precap","連續型":"captype","窗孔型":"captype","不連續型":"captype","靜脈":"vein","骨骼肌幫浦":"musclepump","呼吸幫浦":"musclepump","靜脈瓣":"venvalve","靜脈曲張":"varicose","動脈粥狀硬化":"atherosclerosis","動脈硬化":"arteriosclerosis","斑塊":"plaque","泡沫細胞":"foamcell","脂肪條紋":"foamcell","LDL":"ldl","低密度脂蛋白":"ldl","HDL":"hdl","高密度脂蛋白":"hdl","斯達汀":"statin","HMG-CoA 還原酶":"statin","C 反應蛋白":"crp","CRP":"crp","缺血":"ischemia","心絞痛":"angina","心肌梗塞":"mi","心律不整":"arrhythmia","心搏過速":"tachy","心搏過緩":"tachy","心房纖維顫動":"afib","心室纖維顫動":"vfib","房室傳導阻滯":"avblock","淋巴":"lymph","微淋巴管":"lymphcap","乳糜管":"lacteal","胸管":"thoracicduct","淋巴結":"lymphnode","脾臟":"spleen","淋巴水腫":"lymphedema","水腫":"edema","乳糜微粒":"chylomicron","中鏈脂肪酸":"mct","MCT":"mct"});

