Object.assign(GL,{"cns":{"t":"中樞神經系統 central nervous system（CNS）","d":"<b>腦</b>與<b>脊髓</b>，負責接收、整合資訊並發出命令。","c":"7.1；第 8 章"},
"pns":{"t":"周邊神經系統 peripheral nervous system（PNS）","d":"腦與脊髓以外的神經：腦神經、脊神經、神經節。分為體神經（骨骼肌）與自主神經（交感、副交感）。","c":"7.1；第 9 章"},
"somatic":{"t":"體神經系統 somatic nervous system","d":"支配<b>骨骼肌</b>、可隨意控制的周邊神經。","c":"7.1"},
"autonomic":{"t":"自主神經系統 autonomic nervous system","d":"支配心肌、平滑肌、腺體的不隨意神經，分交感與副交感。","c":"第 9 章"},
"ganglion":{"t":"神經節 ganglion","d":"周邊神經系統中神經元細胞本體的群集（在中樞叫神經核）。","c":"7.1"},
"nissl":{"t":"尼氏小體 Nissl bodies","d":"神經元細胞本體中大量的粗糙內質網，染色後呈顆粒狀，負責大量合成蛋白質。","n":"以德國神經學家 Franz Nissl 命名。","c":"7.1"},
"hillock":{"t":"軸丘 axon hillock","d":"軸突從細胞本體發出的起點，附近的起始段 Na⁺ 通道最多，是動作電位<b>產生</b>的地方，也是突觸輸入「計分」的地方。","c":"7.1、7.7"},
"axtrans":{"t":"軸突運輸 axonal transport","d":"沿著微管在細胞本體與軸突末梢之間運送物質：<b>順向</b>（往末梢，kinesin）、<b>逆向</b>（往本體，dynein）。","e":"狂犬病毒、破傷風毒素利用逆向運輸進入中樞。","c":"7.1"},
"sensoryn":{"t":"感覺（傳入）神經元 sensory / afferent neuron","d":"把感受器的訊號傳<b>入</b>中樞，多為偽單極神經元，細胞本體在背根神經節。","c":"7.1"},
"motorn":{"t":"運動（傳出）神經元 motor / efferent neuron","d":"把中樞的命令傳<b>出</b>到肌肉或腺體，多為多極神經元。","c":"7.1"},
"intern":{"t":"聯絡神經元 interneuron","d":"只在中樞神經系統內，連接感覺與運動神經元、負責整合，數量最多。","c":"7.1"},
"neuroglia2":{"t":"神經膠細胞 neuroglia","d":"神經系統中不傳遞衝動的支持細胞，數量約為神經元的 5 倍，可以分裂（腦瘤多源自膠細胞）。","c":"7.1"},
"satellite":{"t":"衛星細胞 satellite cells","d":"周邊神經系統中包圍神經節細胞本體的支持細胞。","c":"7.1"},
"astro":{"t":"星狀膠細胞 astrocytes","d":"中樞最多的膠細胞，呈星狀：誘導血腦障壁、清除多餘 K⁺ 與麩胺酸、供應神經元乳酸、參與突觸功能與疤痕形成。","c":"7.1"},
"microglia":{"t":"微膠細胞 microglia","d":"中樞神經系統的吞噬細胞，負責免疫防禦與清除碎片。","c":"7.1"},
"ependymal":{"t":"室管膜細胞 ependymal cells","d":"襯在腦室與脊髓中央管的細胞，參與腦脊髓液的形成與流動。","c":"7.1；第 8 章"},
"neurilemma":{"t":"神經膜 neurilemma","d":"許旺細胞最外層含細胞核與細胞質的部分；周邊神經再生時形成再生管引導軸突。中樞沒有。","c":"7.1"},
"ranvier":{"t":"蘭氏結 nodes of Ranvier","d":"兩段髓鞘之間的裸露軸突，電壓閘控 Na⁺ 通道集中在此，動作電位在結與結之間跳躍。","n":"以法國組織學家 Louis-Antoine Ranvier 命名。","c":"7.1、7.2"},
"whitematter":{"t":"白質、灰質 white / gray matter","d":"<b>白質</b>：有髓鞘的軸突集中處，呈白色。<b>灰質</b>：神經元細胞本體與樹突集中處。","c":"7.1；第 8 章"},
"neurotroph":{"t":"神經營養因子 neurotrophins","d":"促進神經元生長、存活與突觸可塑性的蛋白質，如 NGF、BDNF。","c":"7.1"},
"bbb":{"t":"血腦障壁 blood-brain barrier","d":"腦微血管內皮細胞以緊密連接相連、沒有開孔，加上星狀膠細胞誘導，限制血中物質進入腦；脂溶性物質可通過，葡萄糖靠 GLUT1。","c":"7.1；第 8 章"},
"graded":{"t":"分級電位 graded potential","d":"大小隨刺激強度而變、傳一段距離就衰減的膜電位變化，發生在樹突與細胞本體（如突觸後電位）。","c":"7.2"},
"ap":{"t":"動作電位 action potential","d":"膜電位達到閾值後，在約 1–2 毫秒內從 −70 衝到約 +30 mV 再回來的電訊號；全有全無、能不衰減地沿軸突傳導。","c":"7.2"},
"vgc":{"t":"電壓閘控通道 voltage-gated channels","d":"依膜電位改變而打開或關閉的離子通道。電壓閘控 Na⁺ 通道快開快失活，K⁺ 通道慢開。","c":"7.2"},
"threshold":{"t":"閾值 threshold","d":"引發動作電位所需的最低去極化程度，神經元約 −55 mV。","n":"「閾」是門檻的意思。","c":"7.2"},
"repol":{"t":"再極化 repolarization","d":"動作電位的下降期：Na⁺ 通道失活、K⁺ 流出，膜電位回到負值。","c":"7.2"},
"allnone":{"t":"全有全無定律 all-or-none law","d":"刺激未達閾值不產生動作電位；達到閾值就產生大小固定的動作電位，不會因刺激更強而變大。","c":"7.2"},
"recruit":{"t":"徵召 recruitment","d":"刺激越強，被活化的神經纖維（或運動單位）越多。","c":"7.2；第 12 章"},
"refract":{"t":"不反應期 refractory period","d":"<b>絕對</b>：Na⁺ 通道失活，再強的刺激也無法引發動作電位。<b>相對</b>：需要比平常更強的刺激。","c":"7.2；第 12、13 章"},
"salt":{"t":"跳躍式傳導 saltatory conduction","d":"有髓鞘軸突上，動作電位只在蘭氏結產生，從一個結「跳」到下一個結，傳得快又省能量。","n":"拉丁文 saltare＝跳躍。","c":"7.2"},
"synapse":{"t":"突觸 synapse","d":"神經元和另一個細胞（神經、肌肉、腺體）傳遞訊號的連接處。","n":"希臘文「連接」。","c":"7.3"},
"nmj":{"t":"神經肌肉接合處 neuromuscular junction","d":"運動神經末梢和骨骼肌纖維之間的突觸，釋放乙醯膽鹼作用在菸鹼型受體。","c":"7.4；第 12 章"},
"svesicle":{"t":"突觸小泡 synaptic vesicles","d":"突觸前末梢內裝著神經傳遞物質的小囊泡，Ca²⁺ 進入時以胞吐方式釋放。","c":"7.3"},
"cleft":{"t":"突觸間隙 synaptic cleft","d":"突觸前與突觸後膜之間約 20–40 nm 的狹窄空隙。","c":"7.3"},
"epsp":{"t":"EPSP、IPSP 突觸後電位","d":"<b>EPSP</b>（興奮性突觸後電位）：去極化，使神經元較易達到閾值。<b>IPSP</b>（抑制性）：過極化，較難達到閾值。","c":"7.3、7.7"},
"reuptake":{"t":"再攝取 reuptake","d":"突觸前末梢把釋放出去的神經傳遞物質回收，終止訊號並重複利用。","e":"SSRI 抗憂鬱藥、古柯鹼阻斷再攝取。","c":"7.3、7.5"},
"ach":{"t":"乙醯膽鹼 acetylcholine（ACh）","d":"由膽鹼與乙醯輔酶 A 合成的神經傳遞物質：骨骼肌的運動神經、所有自主神經節前神經元、副交感節後神經元都釋放它。","c":"7.4；第 9、12 章"},
"nicotinic":{"t":"菸鹼型受體 nicotinic receptor","d":"乙醯膽鹼的離子通道型受體（尼古丁也能活化），在骨骼肌與自主神經節，作用快、使細胞去極化。箭毒可阻斷。","c":"7.4；第 9 章"},
"muscarinic":{"t":"毒蕈鹼型受體 muscarinic receptor","d":"乙醯膽鹼的 G 蛋白偶聯受體（毒菇中的毒蕈鹼也能活化），在副交感神經的標的器官，可興奮或抑制。阿托平可阻斷。","c":"7.4；第 9 章"},
"lgc":{"t":"配體閘控通道 ligand-gated channel","d":"化學物質（配體）結合後才打開的離子通道，例如菸鹼型乙醯膽鹼受體、GABA<sub>A</sub> 受體。","c":"7.4"},
"ache":{"t":"乙醯膽鹼酯酶 acetylcholinesterase（AChE）","d":"在突觸間隙把乙醯膽鹼分解成乙酸與膽鹼、終止訊號的酵素。","e":"有機磷農藥、神經毒氣抑制它 → ACh 堆積中毒。","c":"7.4"},
"choline":{"t":"膽素（膽鹼）choline","d":"製造<b>細胞膜（卵磷脂）</b>、神經傳導物質<b>乙醯膽鹼</b>，並提供<b>甲基</b>的營養素；身體能自己合成一部分，但不夠用。","c":"7.4；營養學","tag":"營養素","nu":"<b>來源</b>：蛋黃（最豐富）、肝臟、肉類、魚、黃豆、十字花科蔬菜。<br><b>建議量</b>（國人 DRIs 第八版，足夠攝取量）：成人男 450、女 390 mg；懷孕 ＋20、哺乳 ＋140；上限攝取量 3,500 mg。<br><b>過量</b>：身體散發魚腥味、低血壓、流汗。","ch":"帶正電的四級銨化合物（三個甲基接在氮上），含三個可提供的甲基。","bc":"①<b>磷脂醯膽鹼（卵磷脂）</b>：細胞膜的主要磷脂質；也是肝臟組裝並送出 VLDL 所必需。<br>②<b>乙醯膽鹼</b>：膽鹼＋乙醯 CoA →（膽鹼乙醯轉移酶）→ 乙醯膽鹼。<br>③氧化成<b>甜菜鹼</b>，把甲基交給同半胱胺酸 → 甲硫胺酸（不需要 B12 的另一條路）。<br>肝臟也能用磷脂醯乙醇胺接上 SAM 的甲基自己合成（PEMT），雌激素促進這條路。","mb":"作為甲基供應者，與葉酸、B12、甲硫胺酸一起維持 SAM，影響 DNA 甲基化；懷孕期胎兒腦部發育的需要量大。","ph":"神經肌肉接合處與副交感神經的乙醯膽鹼（第 7、9 章）；細胞膜構造（第 3、6 章）；肝臟脂質輸出（第 19 章）。","dt":"<b>長期全靜脈營養</b>：缺乏時肝臟送不出 VLDL → <b>脂肪肝</b>、肝指數上升。<br><b>懷孕與哺乳</b>：需要量增加。<br>停經後女性自行合成較少，較容易不足。","m":"<b>膽素三用途：做膜、做乙醯膽鹼、給甲基</b>；最好的來源是<b>蛋黃</b>。","ex":"缺乏的典型表現是<b>脂肪肝</b>（VLDL 無法送出）與肌肉損傷；嚴格說不是維生素，但已訂有足夠攝取量。"},
"atropine":{"t":"阿托平 atropine","d":"阻斷毒蕈鹼型受體的藥物：使瞳孔放大、心跳加快、口乾；用來治療有機磷中毒。","n":"來自顛茄（Atropa belladonna）。","c":"7.4；第 9 章"},
"curare":{"t":"箭毒 curare","d":"阻斷骨骼肌菸鹼型受體的毒素，使骨骼肌（包括呼吸肌）麻痺；南美原住民塗在箭上狩獵。手術用的肌肉鬆弛劑原理類似。","c":"7.4"},
"mg":{"t":"重症肌無力 myasthenia gravis","d":"自體免疫疾病：抗體破壞骨骼肌的乙醯膽鹼菸鹼型受體，肌肉容易疲勞無力（眼瞼下垂常見）；用可逆的 AChE 抑制劑治療。","c":"7.4；第 12 章"},
"endplate":{"t":"運動終板 motor end plate","d":"骨骼肌細胞膜上接受運動神經末梢的特化區域，有大量菸鹼型受體；產生的去極化叫終板電位。","c":"7.4；第 12 章"},
"monoamine":{"t":"單胺類 monoamines","d":"由胺基酸衍生、含一個胺基的神經傳遞物質：血清素、多巴胺、正腎上腺素、腎上腺素、組織胺。","c":"7.5"},
"catechol":{"t":"兒茶酚胺 catecholamines","d":"由<b>酪胺酸</b>合成的一群單胺：<b>多巴胺、正腎上腺素、腎上腺素</b>。","c":"7.5；第 9、11 章"},
"serotonin":{"t":"血清素 serotonin（5-HT）","d":"由<b>色胺酸</b>合成的神經傳遞物質，調節情緒、睡眠、食慾、體溫；約 90% 在腸道。","n":"最早在血清（serum）中發現能收縮血管（tonic）而得名。","c":"7.5"},
"dopamine":{"t":"多巴胺 dopamine","d":"由酪胺酸 → L-多巴合成的兒茶酚胺：黑質紋狀體路徑控制運動（缺乏 → 帕金森氏症），中腦邊緣路徑與獎賞、成癮有關。","c":"7.5；第 8 章"},
"ne":{"t":"正腎上腺素 norepinephrine","d":"交感神經節後神經元的神經傳遞物質；在腦中由藍斑核釋放，與清醒、警覺有關；也是腎上腺髓質分泌的激素之一。","c":"7.5；第 9 章"},
"epi2":{"t":"腎上腺素 epinephrine（adrenaline）","d":"主要由腎上腺髓質分泌的兒茶酚胺激素，參與「戰或逃」反應：心跳加快、血糖上升。","c":"第 9、11 章"},
"mao":{"t":"單胺氧化酶 monoamine oxidase（MAO）","d":"分解單胺類（血清素、多巴胺、正腎上腺素、酪胺）的酵素；MAO 抑制劑是一類抗憂鬱藥。","c":"7.5"},
"tyramine":{"t":"酪胺 tyramine","d":"熟成起司、醃漬發酵食物、紅酒、煙燻肉中的胺類，會促使正腎上腺素釋放；平常被 MAO 分解。服 MAO 抑制劑者大量攝取 → 高血壓危象。","c":"7.5；膳食療養"},
"ldopa":{"t":"L-多巴 L-dopa","d":"多巴胺的前驅物，可經胺基酸載體通過血腦障壁，在腦中轉成多巴胺；用來治療帕金森氏症。","c":"7.1、7.5"},
"ssri":{"t":"選擇性血清素再攝取抑制劑 SSRI","d":"阻止血清素被突觸前末梢回收，延長其作用的抗憂鬱藥，如百憂解。","c":"7.5"},
"parkinson":{"t":"帕金森氏症 Parkinson's disease","d":"中腦黑質的多巴胺神經元退化，造成靜止型顫抖、僵硬、動作遲緩；以 L-多巴治療。","c":"7.5；第 8 章"},
"gaba":{"t":"GABA γ-胺基丁酸","d":"腦中最主要的<b>抑制性</b>神經傳遞物質，打開 Cl⁻ 通道使神經元過極化；由麩胺酸脫羧而成（需維生素 B6）。苯二氮平、酒精增強其作用。","c":"7.6"},
"glycine2":{"t":"甘胺酸 glycine（神經傳遞物質）","d":"脊髓與腦幹主要的抑制性神經傳遞物質，打開 Cl⁻ 通道；番木鱉鹼阻斷其受體造成痙攣。","c":"7.6"},
"excito":{"t":"興奮毒性 excitotoxicity","d":"麩胺酸過量釋放（如中風時），使 Ca²⁺ 大量湧入神經元而造成死亡。","c":"7.6"},
"nmda":{"t":"NMDA、AMPA 受體","d":"兩種麩胺酸離子通道型受體。<b>AMPA</b> 讓 Na⁺ 進入產生 EPSP；<b>NMDA</b> 在去極化時才開，讓 Ca²⁺ 進入，觸發長期增益（LTP）。","c":"7.6、7.7"},
"substp":{"t":"P 物質 substance P","d":"痛覺感覺神經在脊髓釋放、傳遞痛覺的胜肽神經傳遞物質。","c":"7.6；第 10 章"},
"opioid":{"t":"內生性鴉片 endogenous opioids","d":"身體自己製造、作用在鴉片受體的胜肽：β-腦內啡、腦啡肽、強啡肽；能止痛、產生愉悅感。","e":"運動後的「跑者高潮」。納洛酮可阻斷鴉片受體。","c":"7.6、7.7；第 10 章"},
"npy":{"t":"神經胜肽 Y neuropeptide Y（NPY）","d":"下視丘中強力<b>促進食慾</b>的神經胜肽。","c":"7.6；第 19 章"},
"endocann":{"t":"內生性大麻素 endocannabinoids","d":"由突觸後神經元合成、逆向作用在突觸前末梢以減少傳遞物質釋放的脂質訊號（anandamide、2-AG）；參與食慾、痛覺、記憶。","c":"7.6"},
"no":{"t":"一氧化氮 nitric oxide（NO）","d":"由精胺酸產生的氣體訊號分子，直接擴散進鄰近細胞產生 cGMP，使平滑肌放鬆（血管擴張、勃起）。","c":"7.6；第 14 章"},
"adenosine":{"t":"腺苷 adenosine","d":"ATP 分解產物；在腦中隨清醒時間累積而促進睡意。咖啡因就是阻斷腺苷受體而提神。","c":"7.6"},
"cotrans":{"t":"共同傳遞物質 cotransmitter","d":"和主要神經傳遞物質一起被釋放的其他分子，例如 ATP 與正腎上腺素一起釋放。","c":"7.6"},
"spatial":{"t":"空間加成、時間加成 spatial / temporal summation","d":"<b>空間</b>：不同突觸同時的突觸後電位相加。<b>時間</b>：同一突觸快速連續的突觸後電位疊加。","c":"7.7；第 12 章"},
"diverg":{"t":"發散、會聚 divergence / convergence","d":"<b>發散</b>：一個神經元影響許多神經元。<b>會聚</b>：許多神經元的訊號集中到一個神經元。","c":"7.7；第 10 章"},
"plastic":{"t":"突觸可塑性 synaptic plasticity","d":"突觸傳遞強度隨使用而增強或減弱的能力，是學習與記憶的基礎。","c":"7.7；第 8 章"},
"ltp":{"t":"長期增益、長期抑制 LTP / LTD","d":"<b>LTP</b>：反覆高頻刺激使突觸長期變強（NMDA → Ca²⁺ → 插入 AMPA）。<b>LTD</b>：低頻刺激使突觸長期變弱（移除 AMPA）。","c":"7.7；第 8 章"},
"hippo":{"t":"海馬迴 hippocampus","d":"大腦顳葉內側的構造，負責把短期記憶轉成長期記憶；LTP 最早在這裡發現。","n":"形狀像海馬。","c":"第 8 章"},
"preinh":{"t":"突觸前抑制、突觸後抑制","d":"<b>突觸後抑制</b>：使突觸後神經元過極化（GABA、甘胺酸），所有輸入都被打折。<b>突觸前抑制</b>：作用在某一條突觸前末梢，減少 Ca²⁺ 流入與傳遞物質釋放，只影響那一條。","c":"7.7"}});
