(function(){
  const sheet=document.createElement('div'); sheet.id='glsheet';
  sheet.innerHTML='<div class="glbox"><button class="glx" aria-label="關閉">✕</button><div class="glbody"></div></div>';
  document.body.appendChild(sheet);
  const close=()=>sheet.classList.remove('show');
  sheet.addEventListener('click',e=>{if(e.target===sheet||e.target.classList.contains('glx'))return close();
    const q=e.target.closest('.glsr'), c=e.target.closest('.glch'); const term=(GL_ALIAS&&Object.keys(GL_ALIAS).find(k=>0))||sheet.querySelector('.glt').lastChild.textContent.split(/[ （(]/)[0];
    if(q){close(); openSearch(q.dataset.q);} else if(c){close(); openSearch(term,+c.dataset.ch);}});
  const row=(lab,cls,txt)=>txt?`<div class="glrow"><span class="gllab ${cls}">${lab}</span><div>${txt}</div></div>`:'';
  window.openGl=id=>{const g=GL[id]; if(!g)return;
    sheet.querySelector('.glbody').innerHTML=`<div class="glt">${g.tag?`<span class="gltag">${g.tag}</span>`:''}${g.t}</div>`+row('白話','l0',g.d)+row('營養學','n1',g.nu)+row('化學','n2',g.ch)+row('生化','n3',g.bc)+row('分生','n4',g.mb)+row('生理','n5',g.ph)+row('膳療','n7',g.dt)+row('在哪裡','l1',g.w)+row('做什麼','l2',g.f)+row('生活例子','l6',g.e)+row('名稱由來','l3',g.n)+row('記法','l4',g.m)+row('國考提醒','n6',g.ex)+row('詳讀','l5',g.c&&g.c.replace(/第 ([\d、 ]+) 章/g,m=>m.replace(/\d+/g,d=>`<a class="glch" data-ch="${d}">${d}</a>`)).replace(/(^|[；、\s])(\d{1,2})\.(\d{1,2})/g,(m,a,c1,c2)=>`${a}<a class="glch" data-ch="${c1}">${c1}.${c2}</a>`))+(window.openSearch?`<button class="glsr" data-q="${g.t.split(/[ （(]/)[0]}">🔍 在各章找「${g.t.split(/[ （(]/)[0]}」</button>`:'');
    sheet.classList.add('show');};
  // 把正文中的名詞包成可點的 span
  const keys=Object.keys(GL_ALIAS).sort((a,b)=>b.length-a.length);
  const re=new RegExp(keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
  const SKIP='script,style,svg,nav,header,footer,h1,h2,h3,h4,.modebar,.q,#glsheet,.en,.en-term,.pichint,.briefhint,.lt,.secbtn,.top,details.terms,.note,.bh,.lv,.lvkey,.bio summary,.chl,.srbar';
  const walker=document.createTreeWalker(document.querySelector('main'),NodeFilter.SHOW_TEXT,{acceptNode:n=>{
    const p=n.parentElement; if(!p||p.closest(SKIP))return NodeFilter.FILTER_REJECT;
    re.lastIndex=0; return re.test(n.nodeValue)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT;}});
  const nodes=[]; while(walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(n=>{
    const t=n.nodeValue, frag=document.createDocumentFragment(); let last=0; re.lastIndex=0; let m;
    while((m=re.exec(t))){
      if(m.index>last) frag.appendChild(document.createTextNode(t.slice(last,m.index)));
      if(!GL_ALIAS[m[0]]){frag.appendChild(document.createTextNode(m[0])); last=m.index+m[0].length; continue;}
      const sp=document.createElement('span'); sp.dataset.gl=GL_ALIAS[m[0]]; sp.textContent=m[0]; frag.appendChild(sp);
      last=m.index+m[0].length;}
    if(last<t.length) frag.appendChild(document.createTextNode(t.slice(last)));
    n.parentNode.replaceChild(frag,n);
  });
  document.addEventListener('click',e=>{const el=e.target.closest('[data-gl]'); if(el){e.preventDefault(); openGl(el.dataset.gl);}});
  window.markGl=()=>{
    document.querySelectorAll('[data-gl]').forEach(b=>{b.classList.remove('gl'); b.removeAttribute('role'); b.removeAttribute('tabindex');});
    document.querySelectorAll('main section').forEach(sec=>{const seen={},seen1={};
      sec.querySelectorAll('[data-gl]').forEach(b=>{
        const sc=b.closest('.oneline')?seen1:seen;
        if(!b.offsetParent||sc[b.dataset.gl])return; sc[b.dataset.gl]=1; b.classList.add('gl'); b.setAttribute('role','button'); b.tabIndex=0;});});
  };
  markGl();
})();
